from typing import List, Optional, Dict, Any
from myai.adapters.openai_models import ChatMessageInput
from myai.adapters.tool_call_prompt_builder import (
    build_edit_continuation_instruction,
    build_post_edit_final_instruction,
    build_serializer_instruction,
    build_tool_instruction,
    wrap_edit_continuation_intent,
    wrap_post_edit_final_intent,
    wrap_user_intent,
)
from myai.adapters.tool_result_classifier import (
    ToolResultKind,
    classify_latest_tool_message,
)

class PromptOverflowError(Exception):
    """Raised when the rendered prompt exceeds the configured maximum budget after truncation."""
    pass

DEFAULT_PROVIDER_BUDGETS: Dict[str, int] = {
    "chatgpt_android": 100000,
    "chatgpt_5_5_thinking_android": 100000,
    "gemini_android": 200000,
    "gemini_3_flash_android": 200000,
    "gemini_3_flash_thinking_android": 200000,
    "gemini_3_1_pro_android": 200000,
}
TOOL_CALL_SERIALIZER_PROVIDERS = {
    "chatgpt_android",
    "chatgpt_5_5_thinking_android",
    "gemini_android",
    "gemini_3_flash_android",
    "gemini_3_flash_thinking_android",
    "gemini_3_1_pro_android",
}
EDIT_TOOL_NAMES = {"apply_patch", "edit_file", "write_file", "delete_file", "edit", "write"}
EDIT_INTENT_MARKERS = (
    "edit",
    "patch",
    "modify",
    "change",
    "add",
    "delete",
    "remove",
    "write",
    "update",
    "append",
    "insert",
    "replace",
    "\uc218\uc815",
    "\ucd94\uac00",
    "\uc0ad\uc81c",
    "\ubcc0\uacbd",
    "\ud328\uce58",
    "\uace0\uccd0",
    "\uc791\uc131",
    "\ub123\uc5b4",
    "\ubc14\uafd4",
)
INSPECT_INTENT_MARKERS = (
    "diff",
    "status",
    "log",
    "show",
    "blame",
    "check",
    "\ucc28\uc774",
    "\ud655\uc778",
    "\ubcc0\uacbd\uc0ac\ud56d",
    "\ubcc0\uacbd \uc0ac\ud56d",
    "\uc0c1\ud0dc",
)
BASH_INSPECT_MARKERS = (
    "git diff",
    "git status",
    "git log",
    "git show",
    "git blame",
    "\uc2e4\ud589\ud558\uace0",
    "\uc2e4\ud589\ud574\uc918",
    "\uc2e4\ud589\ud574 \uc918",
)


def _tool_names(tools: Optional[List[Dict]]) -> set[str]:
    names: set[str] = set()
    for tool in tools or []:
        if tool.get("type") == "function" and isinstance(tool.get("function"), dict):
            name = tool["function"].get("name")
            if name:
                names.add(name)
    return names


def _latest_user_content(messages: List[ChatMessageInput]) -> Optional[str]:
    for msg in reversed(messages):
        if msg.role == "user" and msg.content:
            return msg.content
    return None


def _looks_like_edit_intent(content: Optional[str]) -> bool:
    if not content:
        return False
    if _looks_like_inspect_intent(content):
        return False
    lowered = content.lower()
    return any(marker in lowered for marker in EDIT_INTENT_MARKERS)

def _looks_like_inspect_intent(content: Optional[str]) -> bool:
    if not content:
        return False
    lowered = content.lower()
    if any(marker in lowered for marker in BASH_INSPECT_MARKERS):
        return True
    matched_inspect = [m for m in INSPECT_INTENT_MARKERS if m in lowered]
    if matched_inspect:
        matched_edit = [m for m in EDIT_INTENT_MARKERS if m in lowered]
        if not matched_edit:
            return True
        all_edit_inside_inspect = all(
            any(em in im for im in matched_inspect)
            for em in matched_edit
        )
        if all_edit_inside_inspect:
            return True
    return False


def _has_edit_tool(tools: Optional[List[Dict]]) -> bool:
    return bool(_tool_names(tools) & EDIT_TOOL_NAMES)


def _intent_kind(content: Optional[str]) -> str:
    if not content:
        return "none"
    lowered = content.lower()
    if any(marker in lowered for marker in BASH_INSPECT_MARKERS):
        return "bash_inspect"
    if _looks_like_inspect_intent(content):
        return "inspect"
    if _looks_like_edit_intent(content):
        return "edit"
    if any(marker in lowered for marker in ("read", "summary", "summarize", "읽", "요약")):
        return "read"
    return "other"


def _requires_tool_call(messages: List[ChatMessageInput], tools: Optional[List[Dict]]) -> bool:
    if not messages or not tools:
        return False
    if messages[-1].role != "user":
        return False
    return _intent_kind(_latest_user_content(messages)) in {"read", "inspect", "edit", "bash_inspect"}


class OpenAIPromptRenderer:
    """Renderer to convert OpenAI-compatible messages array into a single string prompt
    suitable for stateless execution via Android provider."""

    @staticmethod
    def render(
        messages: List[ChatMessageInput],
        max_characters: Optional[int] = None,
        tools: Optional[List[Dict]] = None,
        canonical_id: Optional[str] = None,
        diagnostics: Optional[Dict[str, Any]] = None,
    ) -> str:
        """Render a list of chat messages into a single text prompt with optional budget constraint.

        Args:
            messages: List of ChatMessageInput objects.
            max_characters: Maximum allowed characters for the rendered prompt.
            tools: Optional list of tools to inject as instructions.
            canonical_id: Optional canonical provider ID for model-specific overrides.
            diagnostics: Optional dictionary to record truncation metrics.

        Returns:
            A single formatted string prompt.

        Raises:
            PromptOverflowError: If mandatory context (system + latest request) exceeds budget.
        """
        if not messages:
            return ""

        # Find the last user message index to determine which tool results are "old"
        last_user_idx = -1
        for i, msg in enumerate(messages):
            if msg.role == "user":
                last_user_idx = i

        system_messages = []
        history_messages = []
        tool_messages = []
        dropped_old_tool_results_count = 0

        # The last message is usually the latest user request or tool result
        last_message = messages[-1]
        previous_messages = messages[:-1]

        for i, msg in enumerate(previous_messages):
            if not msg.content:
                continue

            if msg.role == "system" or msg.role == "developer":
                system_messages.append(msg.content)
            elif msg.role == "tool" or msg.role == "function":
                # TASK-164: Drop tool results occurring before the last user message.
                # These are from previous tool-use loops and are no longer needed
                # for the current completion once a new user message has been received.
                if i < last_user_idx:
                    dropped_old_tool_results_count += 1
                    continue

                name_str = f" ({msg.name})" if msg.name else ""
                tool_messages.append(f"Tool{name_str}: {msg.content}")
            else:
                role_str = "User" if msg.role == "user" else "Assistant"
                history_messages.append(f"{role_str}: {msg.content}")

        if diagnostics is not None:
            diagnostics["dropped_old_tool_results_count"] = dropped_old_tool_results_count

        latest_user_intent = _latest_user_content(messages)
        is_serializer_mode = canonical_id in TOOL_CALL_SERIALIZER_PROVIDERS and _requires_tool_call(messages, tools)

        # Classify tool result to decide edit continuation vs post-edit final
        tool_result_cls = classify_latest_tool_message(messages)
        tool_result_kind = tool_result_cls.kind if tool_result_cls else None

        # Edit continuation is allowed ONLY when the tool result is a
        # context-acquisition result (read, glob, grep, other) — NOT
        # when the edit already succeeded or failed.
        _edit_continuation_eligible = (
            tool_result_kind in {
                ToolResultKind.READ_RESULT,
                ToolResultKind.OTHER,
                None,
            }
        )
        is_edit_continuation_mode = (
            canonical_id in TOOL_CALL_SERIALIZER_PROVIDERS
            and bool(tools)
            and last_message.role in {"tool", "function"}
            and _has_edit_tool(tools)
            and _looks_like_edit_intent(latest_user_intent)
            and _edit_continuation_eligible
        )

        # Post-edit final mode: edit succeeded, no more edits needed
        is_post_edit_final_mode = (
            canonical_id in TOOL_CALL_SERIALIZER_PROVIDERS
            and bool(tools)
            and last_message.role in {"tool", "function"}
            and tool_result_kind == ToolResultKind.EDIT_SUCCESS
        )

        if tools:
            if is_serializer_mode or is_edit_continuation_mode:
                tool_instr = build_serializer_instruction(tools)
                if is_edit_continuation_mode:
                    tool_instr += build_edit_continuation_instruction(tools)
            elif is_post_edit_final_mode:
                tool_instr = build_tool_instruction(tools)
                tool_instr += build_post_edit_final_instruction()
            else:
                tool_instr = build_tool_instruction(tools)

            system_messages.append(tool_instr)

        last_content = last_message.content
        if is_serializer_mode and last_content:
            last_content = wrap_user_intent(last_content)
        elif is_edit_continuation_mode and latest_user_intent:
            if last_message.content:
                name_str = f" ({last_message.name})" if last_message.name else ""
                tool_messages.append(f"Tool{name_str}: {last_message.content}")
            last_content = wrap_edit_continuation_intent(latest_user_intent)
        elif is_post_edit_final_mode and latest_user_intent:
            if last_message.content:
                name_str = f" ({last_message.name})" if last_message.name else ""
                tool_messages.append(f"Tool{name_str}: {last_message.content}")
            last_content = wrap_post_edit_final_intent(latest_user_intent)

        def build_prompt(sys_msg: List[str], hist_msg: List[str], tool_msg: List[str], last_content: Optional[str]) -> str:
            blocks = []
            if sys_msg:
                blocks.append("[System Context]\n" + "\n\n".join(sys_msg))
            if hist_msg:
                blocks.append("[Conversation History]\n" + "\n\n".join(hist_msg))
            if tool_msg:
                blocks.append("[Tool Results]\n" + "\n\n".join(tool_msg))
            if last_content:
                blocks.append(f"[Latest Request]\n{last_content}")
            return "\n\n".join(blocks)

        if not max_characters:
            return build_prompt(system_messages, history_messages, tool_messages, last_content)

        mandatory_prompt = build_prompt(system_messages, [], [], last_content)
        if len(mandatory_prompt) > max_characters:
            raise PromptOverflowError(
                f"System context and latest request alone exceed the budget of {max_characters} characters."
            )

        current_history = history_messages.copy()
        current_tool = tool_messages.copy()

        prompt = build_prompt(system_messages, current_history, current_tool, last_content)

        # Truncation Policy 1: Drop oldest history messages first
        history_truncation_count = 0
        while len(prompt) > max_characters and current_history:
            current_history.pop(0)
            history_truncation_count += 1
            prompt = build_prompt(system_messages, current_history, current_tool, last_content)

        # Truncation Policy 2: Drop oldest tool results if still over budget
        tool_truncation_count = 0
        while len(prompt) > max_characters and current_tool:
            current_tool.pop(0)
            tool_truncation_count += 1
            prompt = build_prompt(system_messages, current_history, current_tool, last_content)

        if diagnostics is not None:
            diagnostics["prompt_truncation_occurred"] = (history_truncation_count + tool_truncation_count) > 0
            diagnostics["prompt_budget_history_truncation_count"] = history_truncation_count
            diagnostics["prompt_budget_tool_truncation_count"] = tool_truncation_count

        return prompt

"""Parses REPL inputs into slash commands or textual tasks."""

from __future__ import annotations

from typing import Any, Dict


class ReplActionType:
    SLASH_COMMAND = "SLASH_COMMAND"
    ASK_TASK = "ASK_TASK"
    EMPTY = "EMPTY"


class CommandParser:
    """Parses raw user input to determine the type of REPL action."""

    @staticmethod
    def parse(user_input: str) -> Dict[str, Any]:
        """Parse raw input.

        Args:
            user_input: Raw string from prompt.

        Returns:
            Dict containing 'type' and either 'command'/'args' or 'task'.
        """
        raw = user_input.strip()
        if not raw:
            return {"type": ReplActionType.EMPTY}

        if raw.startswith("/"):
            parts = raw.split(" ", 1)
            cmd = parts[0]
            args = parts[1].strip() if len(parts) > 1 else ""
            return {
                "type": ReplActionType.SLASH_COMMAND,
                "command": cmd,
                "args": args,
            }

        return {
            "type": ReplActionType.ASK_TASK,
            "task": raw,
        }

"""System diagnostic tool for Ariadne CLI."""

from __future__ import annotations

import json
import os
import subprocess
import sys
from dataclasses import dataclass
from pathlib import Path
from urllib import error as urlerror
from urllib import request as urlrequest

from myai import __version__
from myai.android.adb_client import AdbClient


DEFAULT_BRIDGE_BASE_URL = "http://127.0.0.1:8000"
_PROVIDER_SPECS = {
    "chatgpt_android": {
        "packages": ["com.openai.chatgpt"],
        "input_markers": ["android.widget.EditText", "message_input", "input_text"],
    },
    "gemini_android": {
        "packages": ["com.google.android.apps.bard", "com.google.android.googlequicksearchbox"],
        "input_markers": [
            "android.widget.EditText",
            "assistant_robin_input_collapsed_text_half_sheet",
            "assistant_robin_send_icon_button",
        ],
    },
}


@dataclass
class _HttpCheck:
    ok: bool
    parseable_json: bool
    http_status: int | None
    error: str | None


def _http_json_check(url: str, timeout: float = 2.5) -> _HttpCheck:
    try:
        with urlrequest.urlopen(url, timeout=timeout) as response:
            raw = response.read()
            status = getattr(response, "status", None)
            try:
                json.loads(raw.decode("utf-8"))
                return _HttpCheck(ok=True, parseable_json=True, http_status=status, error=None)
            except (UnicodeDecodeError, json.JSONDecodeError):
                return _HttpCheck(ok=True, parseable_json=False, http_status=status, error="non_json_response")
    except (urlerror.URLError, TimeoutError) as exc:
        return _HttpCheck(ok=False, parseable_json=False, http_status=None, error=str(exc))


def _run_adb(adb_path: str, args: list[str], timeout: float = 3.0) -> tuple[bool, str]:
    try:
        result = subprocess.run(
            [adb_path, *args],
            capture_output=True,
            text=True,
            timeout=timeout,
        )
    except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
        return False, ""
    if result.returncode != 0:
        return False, result.stdout + result.stderr
    return True, result.stdout


def _is_package_installed(adb_path: str, device: str, package: str) -> bool:
    ok, output = _run_adb(adb_path, ["-s", device, "shell", "pm", "path", package])
    return ok and "package:" in output


def _get_foreground_package(adb_path: str, device: str) -> str | None:
    ok, output = _run_adb(adb_path, ["-s", device, "shell", "dumpsys", "window"])
    if not ok:
        return None
    for line in output.splitlines():
        if "mCurrentFocus=" in line or "mFocusedApp=" in line:
            for token in line.replace("/", " ").split():
                if "." in token and token.startswith("com."):
                    return token.split("/")[0]
    return None


def _check_input_ready_heuristic(adb_path: str, device: str, markers: list[str]) -> bool:
    ok, output = _run_adb(adb_path, ["-s", device, "shell", "uiautomator", "dump", "/dev/tty"], timeout=5.0)
    if not ok:
        return False
    lowered = output.lower()
    return any(marker.lower() in lowered for marker in markers)


def _provider_state(adb_path: str, online_devices: int, primary_device: str | None) -> dict[str, dict]:
    results: dict[str, dict] = {}
    for provider, spec in _PROVIDER_SPECS.items():
        if online_devices <= 0 or not primary_device:
            results[provider] = {
                "status": "unknown",
                "installed": False,
                "login_ready": False,
                "foreground_input_ready": False,
                "reason": "device_offline",
            }
            continue
        installed = any(_is_package_installed(adb_path, primary_device, pkg) for pkg in spec["packages"])
        foreground_package = _get_foreground_package(adb_path, primary_device)
        in_foreground = bool(foreground_package and foreground_package in spec["packages"])

        # Enhanced heuristic for ChatGPT to detect current model
        current_model = None
        input_ready = False

        if in_foreground:
            # We dump the UI once and use it for both input ready check and model detection
            ok, output = _run_adb(adb_path, ["-s", primary_device, "shell", "uiautomator", "dump", "/dev/tty"], timeout=5.0)
            if ok:
                lowered = output.lower()
                input_ready = any(marker.lower() in lowered for marker in spec["input_markers"])

                if provider == "chatgpt_android":
                    import re
                    # Look for 5.5 Thinking or other known models
                    match = re.search(r'text="([^"]*5\.5[^"]*Thinking[^"]*)"', output, re.IGNORECASE)
                    if not match:
                        match = re.search(r'content-desc="([^"]*5\.5[^"]*Thinking[^"]*)"', output, re.IGNORECASE)

                    if match:
                        current_model = "5.5 Thinking"
                    else:
                        # Fallback: catch common model names in UI, limited to 30 characters to avoid data exposure
                        match = re.search(r'text="((?:GPT-4o|o1|o3|Thinking)[^"]{0,30})"', output, re.IGNORECASE)
                        if match:
                            current_model = match.group(1)

        login_ready = installed and input_ready
        status = "ok" if login_ready else "warning"
        reason = "ready" if login_ready else ("not_installed" if not installed else "not_foreground_or_input_unready")

        results[provider] = {
            "status": status,
            "installed": installed,
            "login_ready": login_ready,
            "foreground_input_ready": input_ready,
            "reason": reason,
        }
        if current_model:
            results[provider]["current_model"] = current_model

    return results


def run_doctor() -> dict:
    """Run diagnostic checks and return a summary payload.

    Returns:
        dict: A dictionary containing diagnostic information.
    """
    status = "ok"

    # 1. Python & Package
    python_version = sys.version.split(" ")[0]
    pkg_version = __version__

    # 2. ADB
    adb = AdbClient()
    devices = adb.get_online_devices()
    adb_status = "ok" if devices else "offline"
    adb_available, _ = _run_adb("adb", ["version"])
    if not adb_available or not devices:
        status = "warning"

    # 3. Local bridge checks
    health = _http_json_check(f"{DEFAULT_BRIDGE_BASE_URL}/health")
    models = _http_json_check(f"{DEFAULT_BRIDGE_BASE_URL}/v1/models")
    bridge_status = "ok" if health.ok else "unreachable"
    models_status = "ok" if (models.ok and models.parseable_json) else "unreachable_or_non_json"
    if bridge_status != "ok" or models_status != "ok":
        status = "warning"

    # 4. Provider heuristics (redacted: no serials or inventory probing)
    provider_checks = _provider_state("adb", len(devices), devices[0] if devices else None)
    if any(item["status"] != "ok" for item in provider_checks.values()):
        status = "warning"

    # 5. Output directory
    output_dir = Path("output")
    out_dir_status = "missing"
    if output_dir.exists() and output_dir.is_dir():
        out_dir_status = "ok"
        if not os.access(output_dir, os.W_OK):
            out_dir_status = "read-only"
            status = "warning"
    else:
        status = "warning"

    return {
        "status": status,
        "python_version": python_version,
        "package_version": pkg_version,
        "bridge_base_url": DEFAULT_BRIDGE_BASE_URL,
        "health_check": {
            "status": bridge_status,
            "http_status": health.http_status,
            "parseable_json": health.parseable_json,
        },
        "models_check": {
            "status": models_status,
            "http_status": models.http_status,
            "parseable_json": models.parseable_json,
        },
        "adb_available": adb_available,
        "adb_status": adb_status,
        "online_devices": len(devices),
        "providers": provider_checks,
        "output_dir_status": out_dir_status,
    }

"""Logs command baseline for listing recent output files."""

from __future__ import annotations

from pathlib import Path


def get_recent_logs(max_count: int = 10) -> dict:
    """Retrieve the most recent markdown files in the output directory.

    Args:
        max_count: Maximum number of log files to return.

    Returns:
        A dictionary containing the status and list of log entries.
    """
    output_dir = Path("output")
    if not output_dir.exists() or not output_dir.is_dir():
        return {"status": "ok", "logs": [], "message": "Output directory does not exist."}

    try:
        # Fetch all .md files and sort by modification time, newest first.
        files = sorted(
            output_dir.glob("*.md"),
            key=lambda p: p.stat().st_mtime,
            reverse=True
        )
    except Exception as e:
        return {"status": "error", "logs": [], "message": f"Error reading output directory: {e}"}

    if not files:
        return {"status": "ok", "logs": [], "message": "No logs found."}

    logs = []
    for f in files[:max_count]:
        stat = f.stat()
        logs.append({
            "filename": f.name,
            "path": str(f),
            "size_bytes": stat.st_size,
            "modified_time": stat.st_mtime,
        })

    return {
        "status": "ok",
        "logs": logs,
        "message": f"Found {len(files)} logs. Showing top {len(logs)}.",
    }

"""REPL loop implementation for interactive sessions."""

from __future__ import annotations

import json
from prompt_toolkit import PromptSession
from prompt_toolkit.patch_stdout import patch_stdout

from myai.cli.command_parser import CommandParser, ReplActionType
from myai.cli.session_state import SessionState
from myai.core.context_collector import collect_context
from myai.core.packet import PacketBuildRequest, PacketBuilder


class ReplLoop:
    """Manages the interactive console loop."""

    def __init__(self) -> None:
        self.state = SessionState()
        # Initialize prompt_toolkit session for features like history and multiline in the future
        self.session: PromptSession[str] = PromptSession()

    def handle_slash_command(self, cmd: str, args: str) -> bool:
        """Process slash commands.

        Returns:
            True to continue REPL, False to exit.
        """
        if cmd == "/exit" or cmd == "/quit":
            return False

        elif cmd == "/help":
            print("Commands: /provider [name], /profile [name], /context [mode], /files [paths], /apply, /verify, /fanout [prov...], /status, /exit")

        elif cmd == "/status":
            self.state.print_status()

        elif cmd == "/fanout":
            if not args:
                print("Usage: /fanout provider1 provider2 ...")
                return True
            providers = args.split()
            task_text = "(mock REPL fanout task)"
            print(f"Running fanout to {providers} for task: '{task_text}' (mock)")
            from myai.cli.fanout import execute_fanout
            from myai.core.packet import PacketBuilder, PacketBuildRequest
            from myai.core.context_collector import collect_context
            ctx = collect_context(mode=self.state.context_mode)
            pkt = PacketBuilder().build(PacketBuildRequest(
                command="fanout", user_task=task_text, context_snapshot=ctx, 
                provider="fanout", profile=self.state.profile))
            summary = execute_fanout(pkt, providers)
            print(summary)

        elif cmd == "/apply":
            from myai.cli.post_process import PostProcessor
            res = PostProcessor.process_apply(self.state.last_ai_response)
            self.state.last_apply_status = res
            print(res)

        elif cmd == "/verify":
            from myai.cli.post_process import PostProcessor
            res = PostProcessor.process_verify()
            print(res)

        elif cmd == "/provider":
            if args:
                self.state.provider = args
                print(f"Provider set to: {self.state.provider}")
            else:
                print(f"Current provider: {self.state.provider}")

        elif cmd == "/profile":
            if args:
                self.state.profile = args
                print(f"Profile set to: {self.state.profile}")
            else:
                print(f"Current profile: {self.state.profile}")

        elif cmd == "/context":
            if args:
                self.state.context_mode = args
                print(f"Context set to: {self.state.context_mode}")
            else:
                print(f"Current context: {self.state.context_mode}")

        elif cmd == "/files":
            if args:
                self.state.files = args.split()
                print(f"Files attached: {self.state.files}")
            else:
                print(f"Current files: {self.state.files}")
        else:
            print(f"Unknown command: {cmd}")

        return True

    def run_one_shot(self, user_task: str) -> None:
        """Execute a one-shot execution path via PacketBuilder."""
        try:
            # We treat REPL inputs as 'ask' by default
            context_snapshot = collect_context(mode=self.state.context_mode)

            packet = PacketBuilder().build(
                PacketBuildRequest(
                    command="ask",
                    user_task=user_task,
                    context_snapshot=context_snapshot,
                    provider=self.state.provider,
                    profile=self.state.profile,
                )
            )
            # In Phase 4, we don't apply execution immediately in MVP, 
            # we just print the built packet, same as the one-shot command surface.
            # Later phases integrate actual staging/verification.
            output = {"status": "packet_built_from_repl", "packet": packet}
            print(json.dumps(output, ensure_ascii=True))

            # Simulate staging an AI response for UX testing
            self.state.last_ai_response = f"```python\n# Mock response for {user_task}\n```"
            print("[Staged a mock AI response in session]")

        except Exception as e:
            print(f"Execution failed: {e}")

    def loop(self) -> None:
        """Run the REPL loop."""
        print("Welcome to Ariadne REPL! Type /help for commands, /exit to quit.")
        while True:
            # Safely patch stdout so that async prints don't interrupt the prompt
            with patch_stdout():
                try:
                    text = self.session.prompt("Ariadne> ")
                except (KeyboardInterrupt, EOFError):
                    break

                parsed = CommandParser.parse(text)
                action_type = parsed.get("type")

                if action_type == ReplActionType.EMPTY:
                    continue
                elif action_type == ReplActionType.SLASH_COMMAND:
                    should_continue = self.handle_slash_command(
                        parsed.get("command", ""),
                        parsed.get("args", "")
                    )
                    if not should_continue:
                        break
                elif action_type == ReplActionType.ASK_TASK:
                    self.run_one_shot(parsed.get("task", ""))


def run_repl() -> int:
    """Entry point for the REPL shell command."""
    repl = ReplLoop()
    repl.loop()
    return 0

"""Session Renderer for CLI and TUI.

Provides human-friendly formatting of session status and events.
"""

from __future__ import annotations

from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from myai.cli.session_state import SessionState
    from myai.core.session_schema import SessionEvent

from myai.core.session_schema import (
    PromptEvent, ResponseEvent, StageEvent,
    ApplyEvent, VerifyEvent, ErrorEvent
)

class SessionRenderer:
    """Renders session state and events into human-readable strings."""

    def __init__(self, use_color: bool = True):
        self.use_color = use_color

    def _style(self, text: str, color: str = "0") -> str:
        """Apply ANSI color styling if enabled."""
        if not self.use_color:
            return text
        # Simple color map
        color_map = {
            "reset": "0",
            "bold": "1",
            "red": "31",
            "green": "32",
            "yellow": "33",
            "blue": "34",
            "magenta": "35",
            "cyan": "36",
            "white": "37",
        }
        code = color_map.get(color, color)
        return f"\033[{code}m{text}\033[0m"

    def render_status(self, state: SessionState, session_id: str, turn_count: int) -> str:
        """Render a summary of the current session state."""
        title = self._style("--- Session Status ---", "bold")
        lines = [
            title,
            f"Session ID : {self._style(session_id, 'cyan')}",
            f"Provider   : {self._style(state.provider, 'green')}",
            f"Profile    : {state.profile}",
            f"Context    : {state.context_mode}",
            f"Turn Count : {turn_count}",
            f"Last Apply : {state.last_apply_status}",
            self._style("-" * 22, "bold")
        ]
        return "\n".join(lines)

    def render_event(self, event: SessionEvent) -> str:
        """Render a single session event into a human-friendly string."""
        if isinstance(event, PromptEvent):
            return self._render_prompt(event)
        elif isinstance(event, ResponseEvent):
            return self._render_response(event)
        elif isinstance(event, StageEvent):
            return self._render_stage(event)
        elif isinstance(event, ApplyEvent):
            return self._render_apply(event)
        elif isinstance(event, VerifyEvent):
            return self._render_verify(event)
        elif isinstance(event, ErrorEvent):
            return self._render_error(event)

        # Fallback for generic or other events
        header = self._style(f"EVENT[{event.sequence}] {event.event_type.upper()}", "bold")
        return f"{header}: {event.to_dict()}"

    def _render_prompt(self, event: PromptEvent) -> str:
        header = self._style("USER >", "blue")
        return f"{header} {event.prompt}"

    def _render_response(self, event: ResponseEvent) -> str:
        header = self._style("AI   >", "green")
        return f"{header} {event.response}"

    def _render_stage(self, event: StageEvent) -> str:
        header = self._style("STAGE>", "magenta")
        files = ", ".join(event.staged_files) if event.staged_files else "(none)"
        return f"{header} Staged files: {files}"

    def _render_apply(self, event: ApplyEvent) -> str:
        header = self._style("APPLY>", "cyan")
        status_color = "green" if event.status == "success" else "red"
        status_str = self._style(event.status, status_color)
        files = ", ".join(event.applied_files) if event.applied_files else "(none)"
        return f"{header} Status: {status_str}, Files: {files}"

    def _render_verify(self, event: VerifyEvent) -> str:
        header = self._style("VERIFY", "yellow")
        status_color = "green" if event.verify_status == "pass" else "red"
        status_str = self._style(event.verify_status, status_color)
        return f"{header} Result: {status_str} - {event.summary}"

    def _render_error(self, event: ErrorEvent) -> str:
        header = self._style("ERROR ", "red")
        return f"{header}: {event.error_message}"

"""TUI Diff Preview Renderer.

Provides unified diff visualization between the current workspace
state and a staged StageRecord, with ANSI color styling for the TUI.
"""

from __future__ import annotations

import difflib
from pathlib import Path
from typing import List

from myai.core.stage_manager import StageRecord


class DiffPreview:
    """Renders a unified diff preview of staged changes."""

    def __init__(self, use_color: bool = True) -> None:
        self.use_color = use_color

    def _style(self, text: str, color_code: str) -> str:
        """Apply ANSI color styling if enabled."""
        if not self.use_color:
            return text
        return f"\033[{color_code}m{text}\033[0m"

    def render(self, stage_record: StageRecord, workspace_root: str | Path) -> str:
        """Generate a colored unified diff for all files in the stage.

        Args:
            stage_record: The StageRecord containing staged file paths.
            workspace_root: The root directory of the user's workspace to compare against.

        Returns:
            A formatted multi-line diff string.
        """
        root = Path(workspace_root)
        lines: List[str] = []

        for entry in stage_record.staged_files:
            rel_path = entry.relative_path
            workspace_file = root / rel_path
            staged_file = Path(entry.staged_path)

            # Read original content (or empty if it's a new file)
            original_lines: List[str] = []
            if workspace_file.exists():
                try:
                    original_lines = workspace_file.read_text(encoding="utf-8").splitlines(keepends=True)
                except Exception as e:
                    original_lines = [f"Error reading original file: {e}\n"]

            # Read staged content
            staged_lines: List[str] = []
            if staged_file.exists():
                try:
                    staged_lines = staged_file.read_text(encoding="utf-8").splitlines(keepends=True)
                except Exception as e:
                    staged_lines = [f"Error reading staged file: {e}\n"]

            # Generate diff
            diff = list(difflib.unified_diff(
                original_lines,
                staged_lines,
                fromfile=f"a/{rel_path}",
                tofile=f"b/{rel_path}",
                n=3
            ))

            if not diff:
                continue

            # Apply color
            for line in diff:
                if line.startswith("---") or line.startswith("+++") or line.startswith("@@"):
                    # Meta: blue (34)
                    lines.append(self._style(line.rstrip('\n'), "34"))
                elif line.startswith("+"):
                    # Addition: green (32)
                    lines.append(self._style(line.rstrip('\n'), "32"))
                elif line.startswith("-"):
                    # Deletion: red (31)
                    lines.append(self._style(line.rstrip('\n'), "31"))
                else:
                    # Context: default
                    lines.append(line.rstrip('\n'))

        if not lines:
            return self._style("No changes detected.", "34")

        return "\n".join(lines)

"""Cancellation state registry for HTTP disconnect handling."""

from __future__ import annotations

import threading
import time
from dataclasses import dataclass, field
from typing import Dict, List, Optional

DEFAULT_MAX_CANCELLATION_RECORDS = 256


@dataclass
class CancellationRecord:
    request_id: str
    run_id: str
    provider_id: str
    created_at: float = field(default_factory=time.time)
    disconnect_detected_at: Optional[float] = None
    cancelled: bool = False
    provider_stop_attempted: bool = False
    provider_stop_succeeded: bool = False
    evidence: List[str] = field(default_factory=list)

    def add_evidence(self, message: str) -> None:
        self.evidence.append(message)


class CancellationRegistry:
    def __init__(self, max_records: int = DEFAULT_MAX_CANCELLATION_RECORDS) -> None:
        self._max_records = max(1, max_records)
        self._records: Dict[str, CancellationRecord] = {}
        self._lock = threading.Lock()

    def _enforce_capacity_locked(self) -> None:
        while len(self._records) > self._max_records:
            oldest_request_id = next(iter(self._records))
            self._records.pop(oldest_request_id, None)

    def start(self, request_id: str, run_id: str, provider_id: str) -> CancellationRecord:
        with self._lock:
            rec = CancellationRecord(request_id=request_id, run_id=run_id, provider_id=provider_id)
            rec.add_evidence("cancellation-tracking-started")
            self._records[request_id] = rec
            self._enforce_capacity_locked()
            return rec

    def get(self, request_id: str) -> Optional[CancellationRecord]:
        with self._lock:
            return self._records.get(request_id)

    def mark_disconnect(self, request_id: str) -> Optional[CancellationRecord]:
        with self._lock:
            rec = self._records.get(request_id)
            if rec is None:
                return None
            rec.cancelled = True
            if rec.disconnect_detected_at is None:
                rec.disconnect_detected_at = time.time()
            rec.add_evidence("http-client-disconnect-detected")
            return rec

    def mark_stop_attempt(self, request_id: str, succeeded: bool) -> Optional[CancellationRecord]:
        with self._lock:
            rec = self._records.get(request_id)
            if rec is None:
                return None
            rec.provider_stop_attempted = True
            rec.provider_stop_succeeded = succeeded
            rec.add_evidence(
                "provider-stop-attempt-succeeded" if succeeded else "provider-stop-attempt-failed"
            )
            return rec

    def clear(self, request_id: str) -> Optional[CancellationRecord]:
        with self._lock:
            return self._records.pop(request_id, None)


_REGISTRY: CancellationRegistry | None = None


def get_cancellation_registry() -> CancellationRegistry:
    global _REGISTRY
    if _REGISTRY is None:
        _REGISTRY = CancellationRegistry()
    return _REGISTRY

"""Domain abstraction for model execution channels.

This module provides the base interface for communicating with any execution
backend (such as the Android bridge, a REST API, or a mock for testing).
It enforces the contract defined in ``docs/05_contracts/api/api_contract.md``.
"""

from __future__ import annotations

import abc
from typing import Any


class ModelChannelClient(abc.ABC):
    """Abstract base class for executing complete packets against a backend.

    Implementations map provider/profile routing hints to concrete logic.
    For the MVP, the primary implementation is an Android device bridge
    that automates a mobile app UI.
    """

    @abc.abstractmethod
    def complete(self, packet: dict[str, Any]) -> str:
        """Send a packet and return the raw text response.

        Args:
            packet: A complete execution payload containing harness metadata
                and context (built by :class:`~myai.core.packet.PacketBuilder`).

        Returns:
            Raw AI response string exactly as returned by the backend.

        Raises:
            ChannelError: If communication fails or a domain rule is violated
                (e.g., DeviceOfflineError, AppNotFoundError).
        """
        pass


class ChannelError(Exception):
    """Base exception for channel-level failures.

    Inheritors must align with ``docs/05_contracts/api/error_contract.md``
    for downstream categorization (e.g., mapping to ``failure_code``).
    """

    @property
    def error_code(self) -> str:
        """Return the string error code from the contract."""
        return "UNKNOWN_CHANNEL_ERROR"


class DeviceOfflineError(ChannelError):
    """Raised when the target execution device is unavailable."""

    @property
    def error_code(self) -> str:
        return "DEVICE_OFFLINE"


class AppNotFoundError(ChannelError):
    """Raised when the provider's target application cannot be launched."""

    @property
    def error_code(self) -> str:
        return "APP_NOT_FOUND"


class UiChangedError(ChannelError):
    """Raised when expected UI elements fall out of sync."""

    @property
    def error_code(self) -> str:
        return "UI_CHANGED"


class CopyFailedError(ChannelError):
    """Raised when response retrieval fails due to clipboard/UI issues."""

    @property
    def error_code(self) -> str:
        return "COPY_FAILED"


class ResponseTimeoutError(ChannelError):
    """Raised when the backend takes too long to indicate completion."""

    @property
    def error_code(self) -> str:
        return "RESPONSE_TIMEOUT"


class DeviceBusyError(ChannelError):
    """Raised when the target execution device is locked by another process."""

    @property
    def error_code(self) -> str:
        return "DEVICE_LOCKED"


class AppNotReadyError(ChannelError):
    """Raised when the target app is in the foreground but not in a ready state."""

    @property
    def error_code(self) -> str:
        return "APP_NOT_READY"


class StaleScreenError(ChannelError):
    """Raised when the screen has not updated for a significant duration during response wait."""

    @property
    def error_code(self) -> str:
        return "STALE_SCREEN"


class PartialCaptureError(ChannelError):
    """Raised when the captured response is incomplete/truncated."""

    @property
    def error_code(self) -> str:
        return "PARTIAL_CAPTURE"

"""Index Manager: Manages the .myai/index.json file.

The index file tracks the latest session, run, and stage IDs,
as well as a list of all known sessions.
"""

import copy
import json
import os
import shutil
import tempfile
from pathlib import Path
from typing import Dict, List, Optional, Any


class IndexManager:
    """Manages the index of sessions, runs, and stages."""

    DEFAULT_DATA = {
        "latest_session": None,
        "latest_run": None,
        "latest_stage": None,
        "sessions": []
    }

    def __init__(self, index_path: Optional[str] = None):
        """Initialize the IndexManager.

        Args:
            index_path: Path to the index.json file. 
                        Defaults to .myai/index.json in the current directory.
        """
        if index_path:
            self.index_path = Path(index_path)
        else:
            self.index_path = Path(".myai/index.json")

        self.data: Dict[str, Any] = copy.deepcopy(self.DEFAULT_DATA)

    def load(self) -> Dict[str, Any]:
        """Load the index from disk.

        If the file does not exist, it initializes with default data.

        Returns:
            The loaded index data.
        """
        if not self.index_path.exists():
            self.data = copy.deepcopy(self.DEFAULT_DATA)
            return self.data

        try:
            with open(self.index_path, "r", encoding="utf-8") as f:
                loaded_data = json.load(f)
                # Ensure all required keys exist
                for key, value in self.DEFAULT_DATA.items():
                    if key not in loaded_data:
                        loaded_data[key] = copy.deepcopy(value)
                self.data = loaded_data
        except (json.JSONDecodeError, IOError):
            # Fallback to default if corrupted
            self.data = copy.deepcopy(self.DEFAULT_DATA)

        return self.data

    def update_session(self, session_id: str) -> None:
        """Update the latest session ID and add it to the sessions list.

        Args:
            session_id: The UUID4 session ID.
        """
        self.data["latest_session"] = session_id
        if session_id not in self.data["sessions"]:
            self.data["sessions"].append(session_id)

    def update_run(self, run_id: str) -> None:
        """Update the latest run ID.

        Args:
            run_id: The run ID.
        """
        self.data["latest_run"] = run_id

    def update_stage(self, stage_id: str) -> None:
        """Update the latest stage ID.

        Args:
            stage_id: The stage ID.
        """
        self.data["latest_stage"] = stage_id

    def save(self) -> None:
        """Save the index to disk atomically.

        Uses a temporary file and renames it to ensure atomicity.
        """
        # Ensure directory exists
        self.index_path.parent.mkdir(parents=True, exist_ok=True)

        fd, temp_path = tempfile.mkstemp(
            dir=self.index_path.parent,
            prefix=".index.json.tmp",
            text=True
        )

        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(self.data, f, indent=2)

            # Atomic rename
            os.replace(temp_path, self.index_path)
        except Exception as e:
            if os.path.exists(temp_path):
                os.remove(temp_path)
            raise e

    @property
    def latest_session(self) -> Optional[str]:
        return self.data.get("latest_session")

    @property
    def latest_run(self) -> Optional[str]:
        return self.data.get("latest_run")

    @property
    def latest_stage(self) -> Optional[str]:
        return self.data.get("latest_stage")

    @property
    def sessions(self) -> List[str]:
        return self.data.get("sessions", [])

