def resolve_provider(name: str) -> str:
    """Resolve a provider name or legacy alias to its canonical ID.

    Args:
        name: Provider name or alias (e.g. 'chatgpt').

    Returns:
        Canonical provider ID (e.g. 'chatgpt_android').

    Raises:
        ValueError: If the provider name or alias is not found.
    """
    if name in CANONICAL_PROVIDERS:
        return name

    for canonical_id, info in CANONICAL_PROVIDERS.items():
        if name in info["aliases"]:
            return canonical_id

    raise ValueError(f"Unknown provider or alias: {name}")

