    Temporary compatibility helper to map canonical IDs to legacy output filenames.
    """
    if canonical_id == "chatgpt_android":
        return "chatgpt"
    if canonical_id == "gemini_android":
        return "gemini"
    return canonical_id

"""Session Event Schema: Defines the domain types for the session transcript system.

These dataclasses are used to record the timeline of a session,
including prompts, responses, tool calls, staging, applying, and verifying.
"""

from __future__ import annotations

import uuid
from dataclasses import dataclass, field, asdict
from typing import Any, Dict, List, Optional, Type


@dataclass(kw_only=True)
class SessionEvent:
    """Base class for all session events."""
    session_id: str
    timestamp: float
    sequence: int
    event_type: str

    def __post_init__(self) -> None:
        try:
            uuid.UUID(self.session_id, version=4)
        except ValueError:
            raise ValueError(f"session_id must be a valid UUID4 string, got: {self.session_id}")

    def to_dict(self) -> Dict[str, Any]:
        """Serialize event to a JSON-compatible dictionary."""
        return asdict(self)

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> SessionEvent:
        """Deserialize from a dictionary into the appropriate subclass."""
        event_type = data.get("event_type")

        # Subclass mapping
        class_map: Dict[str, Type[SessionEvent]] = {
            "prompt": PromptEvent,
            "response": ResponseEvent,
            "stage": StageEvent,
            "apply": ApplyEvent,
            "verify": VerifyEvent,
            "tool_call": ToolCallEvent,
            "tool_result": ToolResultEvent,
            "approval": ApprovalEvent,
            "resume_point": ResumePointEvent,
            "error": ErrorEvent,
        }

        target_cls = class_map.get(event_type, cls)
        return target_cls(**data)


@dataclass(kw_only=True)
class PromptEvent(SessionEvent):
    event_type: str = "prompt"
    prompt: str
    context_mode: Optional[str] = None


@dataclass(kw_only=True)
class ResponseEvent(SessionEvent):
    event_type: str = "response"
    response: str
    parsed_actions: List[Dict[str, Any]] = field(default_factory=list)


@dataclass(kw_only=True)
class StageEvent(SessionEvent):
    event_type: str = "stage"
    stage_id: str
    staged_files: List[str] = field(default_factory=list)


@dataclass(kw_only=True)
class ApplyEvent(SessionEvent):
    event_type: str = "apply"
    apply_id: str
    status: str
    applied_files: List[str] = field(default_factory=list)
    blocked_files: List[str] = field(default_factory=list)


@dataclass(kw_only=True)
class VerifyEvent(SessionEvent):
    event_type: str = "verify"
    verify_status: str
    summary: str


@dataclass(kw_only=True)
class ToolCallEvent(SessionEvent):
    event_type: str = "tool_call"
    tool_name: str
    arguments: Dict[str, Any]


@dataclass(kw_only=True)
class ToolResultEvent(SessionEvent):
    event_type: str = "tool_result"
    tool_name: str
    result: Any


@dataclass(kw_only=True)
class ApprovalEvent(SessionEvent):
    event_type: str = "approval"
    decision: str
    reason: Optional[str] = None


@dataclass(kw_only=True)
class ResumePointEvent(SessionEvent):
    event_type: str = "resume_point"
    state_summary: str


@dataclass(kw_only=True)
class ErrorEvent(SessionEvent):
    event_type: str = "error"
    error_message: str
    traceback: Optional[str] = None

"""Base abstractions for agent tools.
"""

from __future__ import annotations

from abc import ABC, abstractmethod
from enum import Enum
from pathlib import Path
from typing import Any, Dict

from myai.tools.schema import ToolResult
from myai.tools.registry import ToolSpec


class ToolPermission(Enum):
    """Permission levels for tools."""
    READ_ONLY = "read_only"
    APPROVAL_REQUIRED = "approval_required"

    def __str__(self) -> str:
        return self.value


class BaseTool(ABC):
    """Abstract base class for all agent tools."""

    @property
    @abstractmethod
    def name(self) -> str:
        """The name of the tool."""

    @property
    @abstractmethod
    def description(self) -> str:
        """A description of what the tool does."""

    @property
    @abstractmethod
    def permission(self) -> ToolPermission:
        """The permission level required to execute the tool."""

    @property
    @abstractmethod
    def parameters(self) -> Dict[str, Any]:
        """The parameter schema for the tool."""

    @abstractmethod
    def execute(self, arguments: Dict[str, Any], workspace: Path) -> ToolResult:
        """Executes the tool with the given arguments.

        Args:
            arguments: The arguments for the tool call.
            workspace: The root path of the workspace to enforce boundaries.

        Returns:
            A ToolResult object.
        """

    def to_spec(self) -> ToolSpec:
        """Converts the tool to a ToolSpec for registry registration.

        Returns:
            A ToolSpec object.
        """
        return ToolSpec(
            name=self.name,
            description=self.description,
            parameters=self.parameters,
            permission=str(self.permission),
        )

    @staticmethod
    def validate_path(relative_path: str, workspace: Path) -> Path:
        """Validates that a path is relative and stays within the workspace.

        Args:
            relative_path: The path provided by the agent.
            workspace: The absolute path of the workspace.

        Returns:
            The resolved absolute Path object.

        Raises:
            ValueError: If the path is absolute or escapes the workspace.
        """
        path = Path(relative_path)
        if path.is_absolute():
            raise ValueError(f"Absolute path not allowed: {relative_path}")

        # Resolve the path relative to the workspace
        resolved = (workspace / path).resolve()

        # Check if the resolved path is within the workspace
        try:
            resolved.relative_to(workspace)
        except ValueError:
            raise ValueError(f"Path escapes workspace: {relative_path}")

        return resolved

"""Delete tool for the agent.
"""

from __future__ import annotations

import datetime
import os
import shutil
from pathlib import Path
from typing import Any, Dict

from myai.tools.base import BaseTool, ToolPermission
from myai.tools.schema import ToolResult
from myai.core.approval_gate import ApprovalGate, ApprovalDecision


class DeleteFileTool(BaseTool):
    """Tool for deleting a file with approval gate and backup."""

    def __init__(self, approval_gate: ApprovalGate) -> None:
        self._approval_gate = approval_gate

    @property
    def name(self) -> str:
        return "delete_file"

    @property
    def description(self) -> str:
        return "Deletes a specified file from the workspace after approval."

    @property
    def permission(self) -> ToolPermission:
        return ToolPermission.APPROVAL_REQUIRED

    @property
    def parameters(self) -> Dict[str, Any]:
        return {
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": "The relative path to the file to delete."
                }
            },
            "required": ["path"]
        }

    def execute(self, arguments: Dict[str, Any], workspace: Path) -> ToolResult:
        path_str = arguments.get("path")

        if not path_str:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error="Missing required argument: path"
            )

        try:
            # 1. Validate path
            resolved_path = self.validate_path(path_str, workspace)

            if not resolved_path.exists():
                return ToolResult(
                    tool_name=self.name,
                    success=False,
                    output=None,
                    error=f"File not found: {path_str}"
                )

            if resolved_path.is_dir():
                return ToolResult(
                    tool_name=self.name,
                    success=False,
                    output=None,
                    error=f"Cannot delete directory: {path_str}. Use a directory deletion tool if available."
                )

            # 2. Request approval
            diff_summary = f"Action: DELETE\nFile: {path_str}"
            decision = self._approval_gate.request_approval(diff_summary)

            if decision != ApprovalDecision.APPROVED:
                return ToolResult(
                    tool_name=self.name,
                    success=False,
                    output=None,
                    error=f"Deletion rejected by user: {getattr(decision, 'reason', 'Rejected')}"
                )

            # 3. Backup and Delete
            backup_dir = workspace / ".myai" / "backups" / "tools" / "deleted"
            backup_dir.mkdir(parents=True, exist_ok=True)

            timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            # Flatten relative path for backup filename to avoid nested dirs in backup
            safe_filename = path_str.replace(os.sep, "_")
            backup_path = backup_dir / f"{safe_filename}.{timestamp}.bak"

            shutil.copy2(resolved_path, backup_path)
            resolved_path.unlink()

            return ToolResult(
                tool_name=self.name,
                success=True,
                output=f"Successfully deleted {path_str} (Backup created: {backup_path.relative_to(workspace)})"
            )

        except ValueError as e:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error=str(e)
            )
        except Exception as e:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error=f"Error deleting file: {str(e)}"
            )

"""Edit tool for the agent.
"""

from __future__ import annotations

import difflib
from pathlib import Path
from typing import Any, Dict, List

from myai.tools.base import BaseTool, ToolPermission
from myai.tools.schema import ToolResult
from myai.core.approval_gate import ApprovalGate, ApprovalDecision


class EditFileTool(BaseTool):
    """Tool for partial file editing using search and replace with approval gate."""

    def __init__(self, approval_gate: ApprovalGate) -> None:
        self._approval_gate = approval_gate

    @property
    def name(self) -> str:
        return "edit_file"

    @property
    def description(self) -> str:
        return (
            "Edits a file by replacing a specific text pattern with new content. "
            "Requires explicit approval of the diff before applying."
        )

    @property
    def permission(self) -> ToolPermission:
        return ToolPermission.APPROVAL_REQUIRED

    @property
    def parameters(self) -> Dict[str, Any]:
        return {
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": "The relative path to the file to edit."
                },
                "search": {
                    "type": "string",
                    "description": "The text pattern to find in the file."
                },
                "replace": {
                    "type": "string",
                    "description": "The text to replace the search pattern with."
                }
            },
            "required": ["path", "search", "replace"]
        }

    def execute(self, arguments: Dict[str, Any], workspace: Path) -> ToolResult:
        path_str = arguments.get("path")
        search_text = arguments.get("search")
        replace_text = arguments.get("replace")

        if not path_str or search_text is None or replace_text is None:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error="Missing required arguments: path, search, and replace"
            )

        try:
            # 1. Validate path
            resolved_path = self.validate_path(path_str, workspace)

            if not resolved_path.exists():
                return ToolResult(
                    tool_name=self.name,
                    success=False,
                    output=None,
                    error=f"File not found: {path_str}"
                )

            # 2. Perform search
            original_content = resolved_path.read_text(encoding="utf-8")
            if search_text not in original_content:
                return ToolResult(
                    tool_name=self.name,
                    success=False,
                    output=None,
                    error=f"Search pattern not found in {path_str}"
                )

            # 3. Create new content (first match only as per constraints)
            new_content = original_content.replace(search_text, replace_text, 1)

            # 4. Generate diff
            diff = difflib.unified_diff(
                original_content.splitlines(keepends=True),
                new_content.splitlines(keepends=True),
                fromfile=f"a/{path_str}",
                tofile=f"b/{path_str}"
            )
            diff_text = "".join(diff)

            # 5. Request approval
            decision = self._approval_gate.request_approval(diff_text)

            if decision != ApprovalDecision.APPROVED:
                return ToolResult(
                    tool_name=self.name,
                    success=False,
                    output=None,
                    error=f"Edit rejected by user: {getattr(decision, 'reason', 'Rejected')}"
                )

            # 6. Apply change
            resolved_path.write_text(new_content, encoding="utf-8")

            return ToolResult(
                tool_name=self.name,
                success=True,
                output=f"Successfully edited {path_str}"
            )

        except ValueError as e:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error=str(e)
            )
        except Exception as e:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error=f"Error editing file: {str(e)}"
            )

"""Git commit tool for the agent.
"""

from __future__ import annotations

import subprocess
from pathlib import Path
from typing import Any, Dict, List

from myai.tools.base import BaseTool, ToolPermission
from myai.tools.schema import ToolResult
from myai.core.approval_gate import ApprovalGate, ApprovalDecision


class GitCommitTool(BaseTool):
    """Tool for staged files and committing changes in a git repository."""

    def __init__(self, approval_gate: ApprovalGate) -> None:
        self._approval_gate = approval_gate

    @property
    def name(self) -> str:
        return "git_commit"

    @property
    def description(self) -> str:
        return "Adds files to git and commits changes with a message after approval."

    @property
    def permission(self) -> ToolPermission:
        return ToolPermission.APPROVAL_REQUIRED

    @property
    def parameters(self) -> Dict[str, Any]:
        return {
            "type": "object",
            "properties": {
                "message": {
                    "type": "string",
                    "description": "The commit message."
                },
                "files": {
                    "type": "array",
                    "items": {"type": "string"},
                    "description": "List of files to add. Defaults to all ('.').",
                    "default": ["."]
                }
            },
            "required": ["message"]
        }

    def execute(self, arguments: Dict[str, Any], workspace: Path) -> ToolResult:
        message = arguments.get("message", "").strip()
        files = arguments.get("files", ["."])

        if not message:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error="Commit message cannot be empty."
            )

        try:
            # 1. Verify git repository
            subprocess.run(
                ["git", "rev-parse", "--is-inside-work-tree"],
                cwd=workspace,
                check=True,
                capture_output=True,
                text=True
            )

            # 2. Generate diff summary for approval gate
            diff_result = subprocess.run(
                ["git", "diff", "--stat", "--cached"] + (["HEAD"] if self._has_commits(workspace) else []),
                cwd=workspace,
                capture_output=True,
                text=True
            )
            # Also include unstaged changes if we are about to 'git add'
            unstaged_diff = subprocess.run(
                ["git", "diff", "--stat"] + files,
                cwd=workspace,
                capture_output=True,
                text=True
            )

            diff_summary = f"Action: GIT_COMMIT\nMessage: {message}\nFiles: {', '.join(files)}\n\n"
            diff_summary += "Changes to be committed (stat):\n"
            diff_summary += (diff_result.stdout or "None (cached)\n")
            diff_summary += "\nChanges to be added (stat):\n"
            diff_summary += (unstaged_diff.stdout or "None\n")

            # 3. Request approval
            decision = self._approval_gate.request_approval(diff_summary)

            if decision != ApprovalDecision.APPROVED:
                return ToolResult(
                    tool_name=self.name,
                    success=False,
                    output=None,
                    error=f"Git commit rejected by user: {getattr(decision, 'reason', 'Rejected')}"
                )

            # 4. Execute git add and git commit
            subprocess.run(["git", "add"] + files, cwd=workspace, check=True)
            commit_result = subprocess.run(
                ["git", "commit", "-m", message],
                cwd=workspace,
                check=True,
                capture_output=True,
                text=True
            )

            # 5. Get the new commit SHA
            sha_result = subprocess.run(
                ["git", "rev-parse", "HEAD"],
                cwd=workspace,
                check=True,
                capture_output=True,
                text=True
            )
            sha = sha_result.stdout.strip()

            return ToolResult(
                tool_name=self.name,
                success=True,
                output=f"Successfully committed changes. SHA: {sha}\n{commit_result.stdout}",
                error=None
            )

        except subprocess.CalledProcessError as e:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error=f"Git command failed: {e.stderr or str(e)}"
            )
        except Exception as e:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error=f"Error during git commit: {str(e)}"
            )

    def _has_commits(self, workspace: Path) -> bool:
        """Checks if the repository has at least one commit."""
        result = subprocess.run(
            ["git", "rev-parse", "HEAD"],
            cwd=workspace,
            capture_output=True
        )
        return result.returncode == 0

"""Git read-only tools for the agent.
"""

from __future__ import annotations

import subprocess
from pathlib import Path
from typing import Any, Dict, List, Optional

from myai.tools.base import BaseTool, ToolPermission
from myai.tools.schema import ToolResult


class GitBaseTool(BaseTool):
    """Common logic for git-related tools."""

    def _run_git(self, args: List[str], cwd: Path) -> subprocess.CompletedProcess:
        """Runs a git command and returns the result.

        Args:
            args: The arguments for the git command.
            cwd: The directory to run the command in.

        Returns:
            A subprocess.CompletedProcess object.

        Raises:
            subprocess.CalledProcessError: If the command fails.
            subprocess.TimeoutExpired: If the command takes too long.
            FileNotFoundError: If git is not installed.
        """
        return subprocess.run(
            ["git"] + args,
            cwd=cwd,
            capture_output=True,
            text=True,
            timeout=30,
            check=True
        )


class GitStatusTool(GitBaseTool):
    """Tool for checking the git status of the workspace."""

    @property
    def name(self) -> str:
        return "git_status"

    @property
    def description(self) -> str:
        return "Shows the current status of the git repository (porcelain format)."

    @property
    def permission(self) -> ToolPermission:
        return ToolPermission.READ_ONLY

    @property
    def parameters(self) -> Dict[str, Any]:
        return {
            "type": "object",
            "properties": {}
        }

    def execute(self, arguments: Dict[str, Any], workspace: Path) -> ToolResult:
        try:
            # git status --porcelain is easier for tools to parse if needed
            # but usually, we just return the raw string to the agent.
            result = self._run_git(["status", "--porcelain"], workspace)
            return ToolResult(
                tool_name=self.name,
                success=True,
                output=result.stdout
            )
        except subprocess.CalledProcessError as e:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error=f"Git status failed (is this a git repo?): {e.stderr.strip()}"
            )
        except subprocess.TimeoutExpired:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error="Git status timed out."
            )
        except FileNotFoundError:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error="Git is not installed on this system."
            )
        except Exception as e:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error=f"Error running git status: {str(e)}"
            )


class GitDiffTool(GitBaseTool):
    """Tool for viewing git diffs."""

    @property
    def name(self) -> str:
        return "git_diff"

    @property
    def description(self) -> str:
        return "Shows the git diff of the workspace or specific files."

    @property
    def permission(self) -> ToolPermission:
        return ToolPermission.READ_ONLY

    @property
    def parameters(self) -> Dict[str, Any]:
        return {
            "type": "object",
            "properties": {
                "staged": {
                    "type": "boolean",
                    "description": "Whether to show staged changes (--cached).",
                    "default": False
                },
                "path": {
                    "type": "string",
                    "description": "Optional relative path to restrict the diff to."
                }
            }
        }

    def execute(self, arguments: Dict[str, Any], workspace: Path) -> ToolResult:
        staged = arguments.get("staged", False)
        path_str = arguments.get("path")

        args = ["diff"]
        if staged:
            args.append("--cached")

        if path_str:
            try:
                resolved_path = self.validate_path(path_str, workspace)
                # git diff takes paths relative to the repo root.
                # Since we run in the workspace root, the relative path works.
                args.append(path_str)
            except ValueError as e:
                return ToolResult(
                    tool_name=self.name,
                    success=False,
                    output=None,
                    error=str(e)
                )

        try:
            result = self._run_git(args, workspace)
            return ToolResult(
                tool_name=self.name,
                success=True,
                output=result.stdout
            )
        except subprocess.CalledProcessError as e:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error=f"Git diff failed: {e.stderr.strip()}"
            )
        except subprocess.TimeoutExpired:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error="Git diff timed out."
            )
        except FileNotFoundError:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error="Git is not installed on this system."
            )
        except Exception as e:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error=f"Error running git diff: {str(e)}"
            )

