    @property
    def description(self) -> str:
        return "Lists files and directories within a given path in the workspace."

    @property
    def permission(self) -> ToolPermission:
        return ToolPermission.READ_ONLY

    @property
    def parameters(self) -> Dict[str, Any]:
        return {
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": "The relative path to list (defaults to '.').",
                    "default": "."
                },
                "recursive": {
                    "type": "boolean",
                    "description": "Whether to list files recursively.",
                    "default": False
                }
            }
        }

    def execute(self, arguments: Dict[str, Any], workspace: Path) -> ToolResult:
        path_str = arguments.get("path", ".")
        recursive = arguments.get("recursive", False)

        try:
            resolved_path = self.validate_path(path_str, workspace)
            if not resolved_path.is_dir():
                return ToolResult(
                    tool_name=self.name,
                    success=False,
                    output=None,
                    error=f"Directory not found: {path_str}"
                )

            entries = []
            if recursive:
                for root, dirs, files in os.walk(resolved_path):
                    root_path = Path(root)
                    for name in dirs + files:
                        full_path = root_path / name
                        rel_path = full_path.relative_to(resolved_path)
                        entries.append(str(rel_path))
            else:
                for item in resolved_path.iterdir():
                    entries.append(item.name)

            return ToolResult(
                tool_name=self.name,
                success=True,
                output=sorted(entries)
            )
        except ValueError as e:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error=str(e)
            )
        except Exception as e:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error=f"Error listing files: {str(e)}"
            )

"""Tool call and result schemas for the agent runtime.

These dataclasses define the standard I/O model for all tools.
"""

from __future__ import annotations

import dataclasses
import uuid
from typing import Any, Dict, Optional


@dataclasses.dataclass
class ToolCall:
    """Represents a request to execute a tool."""
    tool_name: str
    arguments: Dict[str, Any]
    call_id: str = dataclasses.field(default_factory=lambda: str(uuid.uuid4()))

    def to_dict(self) -> Dict[str, Any]:
        """Serialize to a JSON-compatible dict."""
        return {
            "tool_name": self.tool_name,
            "arguments": self.arguments,
            "call_id": self.call_id,
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> ToolCall:
        """Deserialize from a dict."""
        if "tool_name" not in data or "arguments" not in data:
            raise ValueError("Missing required fields: tool_name or arguments")

        return cls(
            tool_name=data["tool_name"],
            arguments=data.get("arguments", {}),
            call_id=data.get("call_id", str(uuid.uuid4())),
        )


@dataclasses.dataclass
class ToolResult:
    """Represents the output of a tool execution."""
    tool_name: str
    success: bool
    output: Any
    error: Optional[str] = None
    duration_ms: Optional[float] = None
    call_id: str = dataclasses.field(default_factory=lambda: str(uuid.uuid4()))

    def to_dict(self) -> Dict[str, Any]:
        """Serialize to a JSON-compatible dict."""
        return {
            "tool_name": self.tool_name,
            "success": self.success,
            "output": self.output,
            "error": self.error,
            "duration_ms": self.duration_ms,
            "call_id": self.call_id,
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> ToolResult:
        """Deserialize from a dict."""
        if "tool_name" not in data or "success" not in data or "output" not in data:
            raise ValueError("Missing required fields: tool_name, success, or output")

        return cls(
            tool_name=data["tool_name"],
            success=data["success"],
            output=data["output"],
            error=data.get("error"),
            duration_ms=data.get("duration_ms"),
            call_id=data.get("call_id", str(uuid.uuid4())),
        )

"""Search tool for the agent.
