from __future__ import annotations

import os
from pathlib import Path
from typing import Any, Dict, List

from myai.tools.base import BaseTool, ToolPermission
from myai.tools.schema import ToolResult


class SearchTool(BaseTool):
    """Tool for searching text within the workspace."""

    @property
    def name(self) -> str:
        return "search"

    @property
    def description(self) -> str:
        return (
            "Searches for a text pattern in files within the workspace. "
            "Returns matching lines with file paths and line numbers."
        )

    @property
    def permission(self) -> ToolPermission:
        return ToolPermission.READ_ONLY

    @property
    def parameters(self) -> Dict[str, Any]:
        return {
            "type": "object",
            "properties": {
                "pattern": {
                    "type": "string",
                    "description": "The text pattern to search for."
                },
                "path": {
                    "type": "string",
                    "description": "The relative path to search within (defaults to '.').",
                    "default": "."
                },
                "case_sensitive": {
                    "type": "boolean",
                    "description": "Whether the search should be case sensitive.",
                    "default": True
                }
            },
            "required": ["pattern"]
        }

    def execute(self, arguments: Dict[str, Any], workspace: Path) -> ToolResult:
        pattern = arguments.get("pattern")
        if not pattern:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error="Missing required argument: pattern"
            )

        path_str = arguments.get("path", ".")
        case_sensitive = arguments.get("case_sensitive", True)
        max_results = 100

        try:
            resolved_root = self.validate_path(path_str, workspace)
            if not resolved_root.is_dir() and not resolved_root.is_file():
                return ToolResult(
                    tool_name=self.name,
                    success=False,
                    output=None,
                    error=f"Path not found: {path_str}"
                )

            results = []

            # Use os.walk for efficiency and handling both files and directories
            search_files = []
            if resolved_root.is_file():
                search_files.append(resolved_root)
            else:
                for root, _, files in os.walk(resolved_root):
                    for file in files:
                        search_files.append(Path(root) / file)

            for file_path in search_files:
                if len(results) >= max_results:
                    break

                try:
                    # Skip binary files by checking if we can read it as text
                    # A better way is to check the first few bytes, but reading a bit works too.
                    with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                        for line_num, line in enumerate(f, 1):
                            if len(results) >= max_results:
                                break

                            match = False
                            if case_sensitive:
                                if pattern in line:
                                    match = True
                            else:
                                if pattern.lower() in line.lower():
                                    match = True

                            if match:
                                rel_path = file_path.relative_to(workspace)
                                results.append({
                                    "file": str(rel_path),
                                    "line": line_num,
                                    "content": line.strip()
                                })
                except Exception:
                    # Skip files that can't be read
                    continue

            return ToolResult(
                tool_name=self.name,
                success=True,
                output=results
            )

        except ValueError as e:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error=str(e)
            )
        except Exception as e:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error=f"Error during search: {str(e)}"
            )

"""Shell execution tool for the agent.
"""

from __future__ import annotations

import subprocess
from pathlib import Path
from typing import Any, Dict

from myai.tools.base import BaseTool, ToolPermission
from myai.tools.schema import ToolResult
from myai.core.approval_gate import ApprovalGate, ApprovalDecision


from myai.tools.shell_policy import ShellPolicy


class RunShellTool(BaseTool):
    """Tool for running shell commands with approval gate and safety policy."""

    MAX_TIMEOUT = 300
    MAX_OUTPUT_CHARS = 10000

    def __init__(self, approval_gate: ApprovalGate, policy: ShellPolicy | None = None) -> None:
        self._approval_gate = approval_gate
        self._policy = policy or ShellPolicy()

    @property
    def name(self) -> str:
        return "run_shell"

    @property
    def description(self) -> str:
        return "Executes a shell command in the workspace after approval."

    @property
    def permission(self) -> ToolPermission:
        return ToolPermission.APPROVAL_REQUIRED

    @property
    def parameters(self) -> Dict[str, Any]:
        return {
            "type": "object",
            "properties": {
                "command": {
                    "type": "string",
                    "description": "The shell command to execute."
                },
                "timeout": {
                    "type": "integer",
                    "description": "The maximum time to run the command in seconds (max 300).",
                    "default": 60
                }
            },
            "required": ["command"]
        }

    def execute(self, arguments: Dict[str, Any], workspace: Path) -> ToolResult:
        command = arguments.get("command")
        timeout = min(arguments.get("timeout", 60), self.MAX_TIMEOUT)

        if not command:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error="Missing required argument: command"
            )

        # 0. Policy check
        policy_result = self._policy.check(command)
        if not policy_result.allowed:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error=f"Shell command rejected by policy: {policy_result.reason}"
            )

        try:
            # 1. Request approval
            diff_summary = f"Action: SHELL_EXECUTE\nCommand: {command}\nCwd: {workspace}"
            decision = self._approval_gate.request_approval(diff_summary)

            if decision != ApprovalDecision.APPROVED:
                return ToolResult(
                    tool_name=self.name,
                    success=False,
                    output=None,
                    error=f"Shell command rejected by user: {getattr(decision, 'reason', 'Rejected')}"
                )

            # 2. Run command
            result = subprocess.run(
                command,
                shell=True,
                cwd=workspace,
                capture_output=True,
                text=True,
                timeout=timeout
            )

            # Combine stdout and stderr
            combined_output = (result.stdout + result.stderr).strip()

            # Cap output length
            if len(combined_output) > self.MAX_OUTPUT_CHARS:
                combined_output = combined_output[:self.MAX_OUTPUT_CHARS] + "\n... (output truncated)"

            return ToolResult(
                tool_name=self.name,
                success=result.returncode == 0,
                output=combined_output,
                error=None if result.returncode == 0 else f"Command exited with code {result.returncode}"
            )

        except subprocess.TimeoutExpired:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error=f"Command timed out after {timeout} seconds."
            )
        except Exception as e:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error=f"Error executing shell command: {str(e)}"
            )

"""Write tool for the agent.
"""

from __future__ import annotations

import datetime
import shutil
from pathlib import Path
from typing import Any, Dict

from myai.tools.base import BaseTool, ToolPermission
from myai.tools.schema import ToolResult
from myai.core.approval_gate import ApprovalGate, ApprovalDecision


class WriteFileTool(BaseTool):
    """Tool for creating or overwriting a file with approval gate."""

    def __init__(self, approval_gate: ApprovalGate) -> None:
        self._approval_gate = approval_gate

    @property
    def name(self) -> str:
        return "write_file"

    @property
    def description(self) -> str:
        return "Creates a new file or overwrites an existing one with the given content."

    @property
    def permission(self) -> ToolPermission:
        return ToolPermission.APPROVAL_REQUIRED

    @property
    def parameters(self) -> Dict[str, Any]:
        return {
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": "The relative path to the file to write."
                },
                "content": {
                    "type": "string",
                    "description": "The content to write to the file."
                }
            },
            "required": ["path", "content"]
        }

    def execute(self, arguments: Dict[str, Any], workspace: Path) -> ToolResult:
        path_str = arguments.get("path")
        content = arguments.get("content")

        if not path_str or content is None:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error="Missing required arguments: path and content"
            )

        try:
            # 1. Validate path
            resolved_path = self.validate_path(path_str, workspace)

            # 2. Request approval
            diff_summary = f"File: {path_str}\nAction: {'Overwrite' if resolved_path.exists() else 'Create'}\nContent size: {len(content)} characters"
            decision = self._approval_gate.request_approval(diff_summary)

            if decision != ApprovalDecision.APPROVED:
                return ToolResult(
                    tool_name=self.name,
                    success=False,
                    output=None,
                    error=f"Operation rejected by user: {getattr(decision, 'reason', 'Rejected')}"
                )

            # 3. Write file (with backup)
            if resolved_path.exists():
                backup_dir = workspace / ".myai" / "backups" / "tools"
                backup_dir.mkdir(parents=True, exist_ok=True)
                timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
                backup_path = backup_dir / f"{resolved_path.name}.{timestamp}.bak"
                shutil.copy2(resolved_path, backup_path)

            resolved_path.parent.mkdir(parents=True, exist_ok=True)
            resolved_path.write_text(content, encoding="utf-8")

            return ToolResult(
                tool_name=self.name,
                success=True,
                output=f"Successfully written to {path_str}"
            )

        except ValueError as e:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error=str(e)
            )
        except Exception as e:
            return ToolResult(
                tool_name=self.name,
                success=False,
                output=None,
                error=f"Error writing file: {str(e)}"
            )

