with open(wbs_file, "r") as f:
    wbs_content = f.read()

task_blocks = re.split(r'(?m)^### (WBS-22-\d{3}): ', wbs_content)[1:]
# This splits into [WBS_ID, BLOCK_CONTENT, WBS_ID, BLOCK_CONTENT, ...]

parsed_tasks = {}
for i in range(0, len(task_blocks), 2):
    wbs_id = task_blocks[i].strip()
    block = task_blocks[i+1]
    lines = block.strip().split('\n')
    title = lines[0].strip()

    data = {'wbs_id': wbs_id, 'title': title}
    current_key = None

    for line in lines[1:]:
        if line.startswith('- TASK:'):
            data['task_id'] = line.split('`')[1]
        elif line.startswith('- 상태:'):
            data['status'] = line.split('`')[1] if '`' in line else line.split(':', 1)[1].strip()
        elif line.startswith('- 설명:'):
            data['desc'] = line.split(':', 1)[1].strip()
        elif line.startswith('- '):
            if ':' in line:
                current_key = line.split(':')[0][2:].strip()
                data[current_key] = []
                val = line.split(':', 1)[1].strip()
                if val:
                    data[current_key].append(val)
            else:
                current_key = "extra"
                if "extra" not in data: data["extra"] = []
                data["extra"].append(line.strip()[2:])
        elif line.startswith('  - ') or line.startswith('    - '):
            if current_key:
                data[current_key].append(line.strip()[2:])

    parsed_tasks[data.get('task_id')] = data

