    return ApplyService(stage_manager, file_writer)


def _manifest(*entries: tuple[str, str]) -> NormalizedManifest:
    m = NormalizedManifest()
    for path, content in entries:
        m.entries.append(
            NormalizedEntry(relative_path=path, content=content, original_path=path)
        )
        m.file_count += 1
    return m


# ---------------------------------------------------------------------------
# Integration tests
# ---------------------------------------------------------------------------

def test_apply_from_stage_id(
    service: ApplyService, stage_manager: StageManager, working_dir: Path
) -> None:
    """Service should lookup by ID and apply via writer."""
    m = _manifest(("hello.py", "print('hi')"))
    staged = stage_manager.stage(m)

    apply_record = service.apply_from_stage(staged.stage_id, auto_approve=True)

    assert apply_record.stage_id == staged.stage_id
    assert apply_record.path_policy_status == "passed"
    assert (working_dir / "hello.py").read_text() == "print('hi')"


def test_apply_from_stage_last(
    service: ApplyService, stage_manager: StageManager, working_dir: Path
) -> None:
    """Service should lookup the latest stage and apply it."""
    # First stage
    m1 = _manifest(("v1.txt", "one"))
    stage_manager.stage(m1)

    # Second (latest) stage
    m2 = _manifest(("v2.txt", "two"))
    staged2 = stage_manager.stage(m2)

    apply_record = service.apply_from_stage("last", auto_approve=True)

    assert apply_record.stage_id == staged2.stage_id
    assert (working_dir / "v2.txt").read_text() == "two"
    assert not (working_dir / "v1.txt").exists()  # m1 was not applied


