    assert "Stage not found" in str(exc.value)


def test_apply_from_stage_last_empty(service: ApplyService) -> None:
    """Service should raise StageNotFoundError if no stages exist for 'last'."""
    with pytest.raises(StageNotFoundError) as exc:
        service.apply_from_stage("last")
    assert "Stage not found" in str(exc.value)

