    try:
        os.symlink(outside, link_path)
    except (OSError, NotImplementedError):
        pytest.skip("Symlinks not supported in this environment")

    # Try to delete/edit/write to the symlink target
    for tool in tools:
        args = {"path": "evil_link"}
        if tool.name == "write_file":
            args["content"] = "overwrite"
        elif tool.name == "edit_file":
            args["search"] = "sensitive"
            args["replace"] = "erased"

        result = tool.execute(args, workspace_dir)

        # BaseTool.validate_path(path, workspace) does:
        # resolved = (workspace / path).resolve()
        # if not resolved.is_relative_to(workspace): raise ValueError
        # Since 'evil_link' resolves to 'outside_marker.txt' which is NOT relative to workspace,
        # it should be caught.

        assert result.success is False
        assert "escapes workspace" in result.error

"""Regression tests for intent classification taxonomy.

Covers the 5-way intent classification introduced in TASK-158:
  - bash_inspect: explicit bash/git command inspection
  - inspect: diff/status/log checking without mutation
  - edit: file mutation intent
  - read: file reading/summary
  - other: general Q&A
"""

import pytest

from myai.adapters.openai_compat import (
    _intent_kind,
    _looks_like_edit_intent,
    _looks_like_inspect_intent,
)


class TestIntentKind:
    """Test _intent_kind() taxonomy classification."""

    # ── bash_inspect ──────────────────────────────────────────────
    @pytest.mark.parametrize(
        "content,expected",
        [
            ("git diff를 실행하고 현재 변경사항이 있는지 설명해줘.", "bash_inspect"),
            ("git status를 확인해줘.", "bash_inspect"),
            ("git log를 보여줘", "bash_inspect"),
            ("git diff 실행해줘", "bash_inspect"),
            ("git show HEAD", "bash_inspect"),
            ("git blame README.md", "bash_inspect"),
        ],
    )
    def test_bash_inspect_intent(self, content, expected):
        assert _intent_kind(content) == expected

    # ── inspect ───────────────────────────────────────────────────
    @pytest.mark.parametrize(
        "content,expected",
        [
            ("현재 diff를 확인해줘", "inspect"),
            ("변경사항을 알려줘", "inspect"),
            ("상태 확인", "inspect"),
        ],
    )
    def test_inspect_intent(self, content, expected):
        assert _intent_kind(content) == expected

    # ── edit ───────────────────────────────────────────────────────
    @pytest.mark.parametrize(
        "content,expected",
        [
            ("README.md를 수정해줘.", "edit"),
            ("README.md에 한 줄 추가해줘.", "edit"),
            ("이 파일을 edit 해줘", "edit"),
            ("apply_patch로 수정해줘", "edit"),
            ("config.py를 삭제해줘", "edit"),
            ("바꿔줘 이 함수를", "edit"),
        ],
    )
    def test_edit_intent(self, content, expected):
        assert _intent_kind(content) == expected

    # ── read ───────────────────────────────────────────────────────
    @pytest.mark.parametrize(
        "content,expected",
        [
            ("README.md를 읽어줘", "read"),
            ("이 파일을 요약해줘", "read"),
            ("summarize this file", "read"),
        ],
    )
    def test_read_intent(self, content, expected):
        assert _intent_kind(content) == expected

    # ── other ──────────────────────────────────────────────────────
    @pytest.mark.parametrize(
        "content,expected",
        [
            ("너의 이름은 뭐야?", "other"),
            ("Hello, how are you?", "other"),
            ("1 + 1은 뭐야?", "other"),
            ("한 줄로 답해줘.", "other"),
        ],
    )
    def test_other_intent(self, content, expected):
        assert _intent_kind(content) == expected

    # ── none ───────────────────────────────────────────────────────
    def test_none_intent(self):
        assert _intent_kind(None) == "none"
        assert _intent_kind("") == "none"


class TestLooksLikeEditIntent:
    """Test _looks_like_edit_intent() does NOT fire for inspection."""

    def test_git_diff_is_not_edit(self):
        """git diff request must NOT be classified as edit intent."""
        assert _looks_like_edit_intent("git diff를 실행하고 현재 변경사항이 있는지 설명해줘.") is False

    def test_git_status_is_not_edit(self):
        assert _looks_like_edit_intent("git status를 확인해줘.") is False

    def test_readme_modify_is_edit(self):
        assert _looks_like_edit_intent("README.md를 수정해줘.") is True

    def test_add_line_is_edit(self):
        assert _looks_like_edit_intent("README.md에 한 줄 추가해줘.") is True

    def test_general_question_is_not_edit(self):
        assert _looks_like_edit_intent("너의 이름은 뭐야?") is False


class TestLooksLikeInspectIntent:
