"""Unit tests for tool_call_validator module.

Covers whitelist, argument type, required field, and bypass scenarios.
"""

import pytest
from myai.adapters.tool_call_validator import (
    ToolCallValidationError,
    validate,
)

SAMPLE_TOOLS = [
    {
        "type": "function",
        "function": {
            "name": "read_file",
            "description": "Read a file",
            "parameters": {
                "type": "object",
                "properties": {
                    "path": {"type": "string"},
                },
                "required": ["path"],
            },
        },
    },
    {
        "type": "function",
        "function": {
            "name": "search",
            "description": "Search",
            "parameters": {
                "type": "object",
                "properties": {
                    "query": {"type": "string"},
                },
            },
        },
    },
]


class TestValidate:
    """Tests for validate function."""

    def test_known_tool_passes(self):
        tc = [{"name": "read_file", "arguments": {"path": "/a.txt"}}]
        result = validate(tc, SAMPLE_TOOLS)
        assert result == tc

    def test_unknown_tool_fails(self):
        tc = [{"name": "invented_tool", "arguments": {}}]
        with pytest.raises(ToolCallValidationError) as exc_info:
            validate(tc, SAMPLE_TOOLS)
        assert exc_info.value.violation.reason_code == "TOOL_CALL_UNKNOWN_TOOL"

    def test_invalid_arguments_type(self):
        tc = [{"name": "read_file", "arguments": "not a dict"}]
        with pytest.raises(ToolCallValidationError) as exc_info:
            validate(tc, SAMPLE_TOOLS)
        assert exc_info.value.violation.reason_code == "TOOL_CALL_INVALID_ARGUMENTS"

    def test_missing_required_param(self):
        tc = [{"name": "read_file", "arguments": {}}]
        with pytest.raises(ToolCallValidationError) as exc_info:
            validate(tc, SAMPLE_TOOLS)
        assert exc_info.value.violation.reason_code == "TOOL_CALL_MISSING_REQUIRED"

    def test_no_tools_bypasses_validation(self):
        tc = [{"name": "anything", "arguments": {"x": 1}}]
        result = validate(tc, None)
        assert result == tc

    def test_tool_without_required_passes(self):
        """Tool 'search' has no required params — empty arguments should pass."""
        tc = [{"name": "search", "arguments": {}}]
        result = validate(tc, SAMPLE_TOOLS)
        assert result == tc

