#!/usr/bin/env python3
"""Create a content-addressed U.2X bundle locally, never executes inference."""
import hashlib
import json
from pathlib import Path
import shutil

ROOT = Path(__file__).resolve().parents[1]


def build():
    sources = {f'scripts/{p.name}': p for p in (ROOT / 'scripts').glob('*.py')}
    sources.update({
        'quality-v1.json': ROOT / 'workloads/track-u/quality-v1.json',
        'contract.md': ROOT / 'docs/track-u/quality-contract.md'
    })
    files = {n: hashlib.sha256(p.read_bytes()).hexdigest() for n, p in sorted(sources.items())}
    data = json.dumps({'files': files}, sort_keys=True, indent=2) + '\n'
    digest = hashlib.sha256(data.encode()).hexdigest()
    dest = ROOT / 'results/tmp' / ('u2x-bundle-' + digest[:12])
    if not dest.exists():
        dest.mkdir(parents=True)
        for n, p in sources.items():
            target = dest / n
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(p, target)
        (dest / 'bundle.json').write_text(data)
    info = {
        'path': str(dest),
        'sha256': digest,
        'remote': '/home/loopwhile/llm-bench/track-u/bundles/' + digest[:12]
    }
    print(json.dumps(info))
    return info


if __name__ == '__main__':
    build()

#!/usr/bin/env python3
"""Read candidate GGUF metadata on P520 without loading tensors or using a GPU."""
import hashlib
import json
from pathlib import Path
import socket
import struct

FORMATS = {0: 'B', 1: 'b', 2: 'H', 3: 'h', 4: 'I', 5: 'i',
           6: 'f', 7: '?', 10: 'Q', 11: 'q', 12: 'd'}
FIELDS = ('nextn', 'recurrent', 'ssm', 'architecture', 'file_type', 'block_count',
          'head_count', 'key_length', 'value_length', 'sliding_window',
          'context_length', 'expert', 'tokenizer.ggml.model', 'tokenizer.ggml.tokens')


def inspect(path):
    with path.open('rb') as stream:
        def unpack(fmt):
            return struct.unpack('<' + fmt, stream.read(struct.calcsize('<' + fmt)))[0]

        def string():
            return stream.read(unpack('Q')).decode()

        def value(kind):
            if kind == 8:
                return string()
            if kind == 9:
                subtype, count = unpack('I'), unpack('Q')
                if count <= 256:
                    return [value(subtype) for _ in range(count)]
                for _ in range(count):
                    value(subtype)
                return {'array_length': count}
            return unpack(FORMATS[kind])

        if stream.read(4) != b'GGUF':
            raise ValueError('Not a GGUF file')
        version, tensors, count = unpack('I'), unpack('Q'), unpack('Q')
        if version != 3:
            raise ValueError(f'Unexpected GGUF version: {version}')
        metadata = {}
        for _ in range(count):
            key = string()
            entry = value(unpack('I'))
            if key == 'tokenizer.chat_template':
                metadata[key + '_sha256'] = hashlib.sha256(entry.encode()).hexdigest()
            elif any(field in key for field in FIELDS):
                metadata[key] = entry
        return {'path': str(path), 'gguf_version': version,
                'tensor_count': tensors, 'metadata': metadata}


def main():
    if socket.gethostname() != 'p520-llm':
        raise SystemExit('Read-only inspection must target p520-llm')
    for model in ('ornith', 'gemma'):
        paths = sorted(Path('/srv/models/p520-lab-candidates', model).glob('*/*.gguf'))
        if not paths:
            raise SystemExit(f'No completed candidate GGUF for {model}')
        for path in paths:
            print(json.dumps(inspect(path)))


if __name__ == '__main__':
    main()

"""Linux-only bounded calls in directly owned, disposable mock worker processes.

No arbitrary PID attachment, process-group signaling, shell or server interface.
"""
import multiprocessing
import os
from pathlib import Path
import signal
import time


class CallTimeout(Exception):
    verdict = 'FAIL_TIMEOUT'


class WorkerFailure(Exception):
    def __init__(self, verdict, message):
        super().__init__(message)
        self.verdict = verdict


class CleanupError(Exception):
    verdict = 'FAIL_CRASH'


def identity(pid):
    fields = Path(f'/proc/{pid}/stat').read_text().rsplit(')', 1)[1].split()
    return {'pid': pid, 'parent_pid': int(fields[1]), 'start_ticks': fields[19],
            'boot_id': Path('/proc/sys/kernel/random/boot_id').read_text().strip()}


def worker(connection, parent_connection, function, args, kwargs):
    parent_connection.close()
    # Foreground terminal interruption is handled by the supervisor only.
    signal.signal(signal.SIGINT, signal.SIG_IGN)
    signal.signal(signal.SIGHUP, signal.SIG_IGN)
    signal.signal(signal.SIGTERM, signal.SIG_DFL)
    try:
        if connection.recv() != 'start':
            return
        try:
            connection.send(('ok', function(*args, **kwargs)))
        except (KeyboardInterrupt, SystemExit) as exc:
            connection.send(('interrupted', type(exc).__name__))
        except BaseException as exc:
            connection.send(('error', getattr(exc, 'verdict', None), str(exc)))
    finally:
        connection.close()


def stop_owned(process, pidfd, recorded, grace_s, events):
    """Never signal a numeric PID. Refuse identity/parent mismatch, even with pidfd."""
    if not process.is_alive():
        process.join(timeout=0)
        events.append({'action': 'already_exited', 'exit_code': process.exitcode})
        return
    try:
        current = identity(process.pid)
    except OSError as exc:
        raise CleanupError('cannot verify live child identity') from exc
    if current != recorded or current['parent_pid'] != os.getpid():
        raise CleanupError('child identity/ownership mismatch; no signal sent')
    for sig in (signal.SIGTERM, signal.SIGKILL):
        try:
            signal.pidfd_send_signal(pidfd, sig)
            events.append({'action': sig.name, 'identity': recorded})
        except ProcessLookupError:
            pass
        process.join(timeout=grace_s)
        if not process.is_alive():
            events.append({'action': 'reaped', 'exit_code': process.exitcode})
            return
    raise CleanupError('owned child did not exit within cleanup grace; manual inspection required')


def bounded_call(function, args=(), kwargs=None, *, deadline, cleanup_grace_s, record):
    """Deadline is absolute monotonic. Record is invoked before work and after cleanup."""
    if not hasattr(os, 'pidfd_open') or not hasattr(signal, 'pidfd_send_signal'):
        raise CleanupError('Linux pidfd support required; no unsafe PID fallback')
    if time.monotonic() >= deadline:
        raise CallTimeout('deadline expired before worker launch')
    probe = os.pidfd_open(os.getpid())
    os.close(probe)
    context = multiprocessing.get_context('fork')
    parent, child = context.Pipe()
    process = context.Process(target=worker, args=(child, parent, function, args, kwargs or {}))
    pidfd = None
    started = False
    events = []
    receipt = {'deadline_monotonic_s': deadline, 'cleanup_grace_s': cleanup_grace_s,
               'owner_pid': os.getpid(), 'worker': None, 'events': events}
    try:
        process.start()
        started = True
        child.close()
        pidfd = os.pidfd_open(process.pid)
        receipt['worker'] = identity(process.pid)
        record('started', receipt)
        parent.send('start')
        remaining = deadline - time.monotonic()
        if remaining <= 0 or not parent.poll(remaining):
            raise CallTimeout('worker deadline expired')
        try:
            message = parent.recv()
        except EOFError as exc:
            raise WorkerFailure('FAIL_CRASH', 'worker exited without a result') from exc
        if time.monotonic() >= deadline:
            raise CallTimeout('worker response arrived after deadline')
        if message[0] == 'interrupted':
            raise KeyboardInterrupt(message[1])
        if message[0] == 'error':
            raise WorkerFailure(message[1], message[2])
        return message[1]
    finally:
        try:
            if started:
                # PID cannot be reused while our unreaped child remains ours. If
                # pidfd creation failed, refuse signals and retain unresolved evidence.
                if pidfd is None or receipt['worker'] is None:
                    parent.close()
                    process.join(timeout=cleanup_grace_s)
                    if process.is_alive():
                        raise CleanupError('worker identity setup failed; cleanup unresolved')
                else:
                    stop_owned(process, pidfd, receipt['worker'], cleanup_grace_s, events)
        except CleanupError as exc:
            receipt['cleanup_error'] = str(exc)
            raise
        finally:
            parent.close()
            child.close()
            if pidfd is not None:
                os.close(pidfd)
            if started:
                record('finished', receipt)

"""Strict evidence gate for Phase 8; missing evidence never becomes a PASS."""

REQUIRED_REVIEW_CHECKS = (
    'capacity_waiting_absent', 'context_shift_absent', 'slot_collision_absent',
    'output_corruption_absent', 'oom_absent', 'crash_absent',
    'hardware_policy_preserved', 'cleanup_verified',
)


def residency_errors(result):
    errors = []
    reqs = result.get('requests', [])
    if result.get('concurrency') != 4 or len(reqs) != 4:
        errors.append('Exactly four requests are required')
    if len({r.get('request_id') for r in reqs}) != 4 or any(not r.get('request_id') for r in reqs):
        errors.append('Four distinct request identities are required')
    for r in reqs:
        if (r.get('status') != 'PASS' or r.get('truncated') is not False
                or r.get('output_tokens') != 128
                or not isinstance(r.get('intended_prompt_tokens'), int)
                or r.get('intended_prompt_tokens', 0) <= 0
                or r.get('prompt_tokens') != r.get('intended_prompt_tokens')):
            errors.append(f"Incomplete or mismatched request: {r.get('request_id')}")
    if result.get('max_simultaneous_slots') != 4:
        errors.append('Missing four-active residency evidence')
    if result.get('postflight_health') != 'PASS':
        errors.append('Missing healthy server after completion')
    return errors


def validate_review(result, review, root):
    """Review stores check -> repo-relative evidence path; never infer from a label.

    The reviewer must inspect full scheduler/log/output/hardware evidence. This
    validator checks completeness and identity, not semantic truth of that review.
    """
    if review.get('experiment_id') != result.get('experiment_id'):
        raise ValueError('Review and result experiment identities differ')
    if review.get('verdict') == 'PASS_RESIDENT':
        errors = residency_errors(result)
        if errors:
            raise ValueError('; '.join(errors))
        checks = review.get('checks', {})
        for name in REQUIRED_REVIEW_CHECKS:
            path = checks.get(name)
            if not path or not (root / path).is_file():
                raise ValueError(f'Missing reviewed evidence: {name}')

#!/usr/bin/env python3
"""Offline Phase 9 validation/planning/metrics. No subprocess, sockets or run import."""
import argparse
import hashlib
import json
import math
from pathlib import Path

IMAGE='sha256:461d786f1281101c547798c44c494feb2c498921cff516e7580531f68187aa43'
BATCHES=((2048,512),(4096,512),(4096,1024),(8192,1024))
CHECKS=('resident_c4','no_queue','no_oom','no_context_shift','no_corruption',
        'cache_clean','hardware_preserved','cleanup_verified')

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def validate_workload(path, model_info):
    receipt=json.loads((path/'receipt.json').read_text())
    work=json.loads((path/'workload.json').read_text())
    if receipt.get('launchable') is not True or receipt.get('image')!=IMAGE:
        raise ValueError('Unverified tokenizer receipt')
    if receipt['model_sha256']!=model_info['sha256']:
        raise ValueError('Model receipt hash mismatch')
    if receipt['workload_sha256']!=sha(path/'workload.json'):
        raise ValueError('Workload hash mismatch')
    for name, digest in receipt['files'].items():
        if Path(name).name!=name or sha(path/name)!=digest:
            raise ValueError('Receipt artifact hash mismatch')
    reqs=work['requests']
    if work['context'] not in (16384,32768) or work['concurrency']!=4 or len(reqs)!=4:
        raise ValueError('Only four-request 16K/32K suites are prepared')
    if len({r['request_id'] for r in reqs})!=4:
        raise ValueError('Duplicate request ID')
    if len({r['raw_prompt'][0] for r in reqs})!=4:
        raise ValueError('Unique leading identifiers required')
    for r in reqs:
        rid=r['request_id']
        if not rid in ('req-01','req-02','req-03','req-04'):
            raise ValueError('Invalid request ID')
        ids=json.loads((path/f'{rid}.tokens.json').read_text())
        if not ids or any(type(i) is not int or i<0 for i in ids):
            raise ValueError('Invalid token IDs')
        if (len(ids)!=work['context']-552 or r['prompt_tokens']!=len(ids)
            or r['raw_token_count']!=len(ids) or r['post_template_token_count']!=len(ids)
            or r['requested_completion_tokens']!=512
            or r['raw_prompt']!=(path/f'{rid}.txt').read_text()
            or r['raw_prompt_sha256']!=sha(path/f'{rid}.txt')
            or r['token_ids_sha256']!=sha(path/f'{rid}.tokens.json')):
            raise ValueError('Prompt/token/output contract mismatch')
    return work

def profile(model, tier, split='layer', batch=2048, ubatch=512):
    if model not in ('qwen','ornith') or tier not in (16384,32768):
        raise ValueError('Out of preparation scope')
    if split not in ('layer','row') or (batch,ubatch) not in BATCHES:
        raise ValueError('Unsupported profile')
    return dict(model=model,context=tier,split=split,batch=batch,ubatch=ubatch,
                tensor_split='1,1',parallel=4,kv='q8_0',unified=True,
                mtp=2 if model=='qwen' else 1,seed=520,temperature=0,
                output_tokens=512,margin=40,cold=True,ignore_eos=True,cache_prompt=False,
                startup_timeout=300,measurement_timeout=1800,cleanup_timeout=60,
                gpu_interval_s=.5,slots_interval_s=.5,image=IMAGE)

def split_pair(model):
    return [profile(model,16384,s) for s in ('layer','row')]

def sweep(model, decision):
    if (decision.get('model')!=model or decision.get('split') not in ('layer','row')
        or decision.get('reviewed') is not True or not decision.get('evidence')
        or decision.get('status')!='validated'):
        raise ValueError('Validated model-specific split evidence required')
    for entry in decision['evidence']:
        path=Path(entry['path'])
        if not path.is_file() or sha(path)!=entry['sha256']:
            raise ValueError('Split evidence missing or altered')
    return [profile(model,16384,decision['split'],b,u) for b,u in BATCHES]

def percentile95(values):
    if not values or any(v is None or not math.isfinite(v) for v in values):
        return None
    return sorted(values)[math.ceil(.95*len(values))-1]

def overlap_proxy(samples):
    valid=overlap=total=0.
    for a,b in zip(samples,samples[1:]):
        dt=b['t_s']-a['t_s']
        if dt<=0:
            raise ValueError('Nonmonotonic telemetry')
        total+=dt
        vals=a.get('utilization')
        if dt>1 or vals is None or len(vals)!=2 or any(v is None for v in vals):
            continue
        valid+=dt
        if all(v>0 for v in vals):
            overlap+=dt
    return {'ratio':overlap/valid if valid else None,'valid_duration_s':valid,
            'coverage':valid/total if total else 0,'actual_kernel_overlap':None,
            'actual_kernel_overlap_reason':'No kernel profiler; utilization is a sampling proxy'}

def metrics(reqs):
    if len(reqs)!=4 or any(r.get('ttft_s') is None for r in reqs):
        return {'unavailable_reason':'Four complete request timings required'}
    wall=max(r['end_s'] for r in reqs)-min(r['submit_s'] for r in reqs)
    mean=lambda v: sum(v)/len(v)
    native=[r.get('decode_tokens_per_s') for r in reqs]
    result={'batch_wall_s':wall,'ttft_mean_s':mean([r['ttft_s'] for r in reqs]),
            'ttft_p95_s':percentile95([r['ttft_s'] for r in reqs]),'ttft_samples':4,
            'mean_decode':mean(native) if all(v is not None for v in native) else None,
            'e2e_output_tok_s':sum(r['output_tokens'] for r in reqs)/wall if wall>0 else None,
            'aggregate_common_decode':None,'client_decode':None,
            'client_decode_reason':'Native adapter preserves text timing; exact token delivery intervals require stream audit',
            'aggregate_reason':'Exact token delivery events unavailable'}
    # Token event data must explicitly be authoritative, never SSE chunk counts.
    if all(r.get('token_events_verified') is True and len(r.get('token_events',[]))>=2
           and r['token_events'][-1]['t_s']>r['token_events'][0]['t_s'] for r in reqs):
        lo=max(r['token_events'][0]['t_s'] for r in reqs)
        hi=min(r['token_events'][-1]['t_s'] for r in reqs)
        result['client_decode']=[sum(e['count'] for e in r['token_events'][1:]) /
            (r['token_events'][-1]['t_s']-r['token_events'][0]['t_s']) for r in reqs]
        if hi>lo:
            result['aggregate_common_decode']=sum(e['count'] for r in reqs for e in r['token_events']
                if lo<e['t_s']<=hi)/(hi-lo)
            result['aggregate_reason']=None
            result['common_interval_s']=[lo,hi]
        result['client_decode_reason']=None
    return result

def classify(result):
    reqs=result.get('requests',[])
    if result.get('oom') is True: return 'FAIL_OOM','oom'
    if result.get('capacity_failure') is True or result.get('queue') is True:
        return 'FAIL_CAPACITY','capacity_or_queue'
    if len(reqs)!=4 or len({r.get('request_id') for r in reqs})!=4:
        return 'INCONCLUSIVE','incomplete_c4'
    for r in reqs:
        if r.get('output_tokens',0)<512 and r.get('natural_eos') is True and not result.get('ignore_eos'):
            return 'INCONCLUSIVE','early_eos'
        if r.get('status')=='FAIL_OUTPUT': return 'FAIL_OUTPUT','output_contract'
        if r.get('status')!='PASS': return 'INCONCLUSIVE','request_failure'
        if r.get('output_tokens')!=512 or r.get('truncated') is not False:
            return 'FAIL_OUTPUT','output_contract'
        if r.get('cache_n')!=0:
            return 'INCONCLUSIVE','cache_reuse_or_missing_evidence'
        if r.get('prompt_tokens')!=r.get('intended_prompt_tokens') or not r.get('prompt_tokens'):
            return 'INCONCLUSIVE','prompt_evaluation_or_cache'
    if result.get('max_simultaneous_slots')!=4 or len({r.get('slot_id') for r in reqs})!=4:
        return 'INCONCLUSIVE','resident_evidence'
    if result.get('postflight_health')!='PASS': return 'INCONCLUSIVE','postflight_health'
    if any(result.get('checks',{}).get(k) is not True for k in CHECKS):
        return 'INCONCLUSIVE','missing_or_failed_review'
    return 'PASS','strict_c4_resident'

def promotion(baseline,candidate):
    for value in (baseline,candidate):
        if classify(value)[0]!='PASS': return {'promote':False,'reason':'strict_gate'}
    if baseline.get('comparison_key') is None or baseline.get('comparison_key')!=candidate.get('comparison_key'):
        return {'promote':False,'reason':'different_model_workload_contract'}
    b,c=baseline['metrics'],candidate['metrics']
    changes={}
    for key in ('batch_wall_s','ttft_mean_s','ttft_p95_s','mean_decode'):
        if not b.get(key) or c.get(key) is None or not all(math.isfinite(x) and x>0 for x in (b[key],c[key])):
            return {'promote':False,'reason':'missing_metrics'}
        changes[key]=100*(c[key]/b[key]-1)
    counts=[v.get('mtp',{}) for v in (baseline,candidate)]
    if any(not x.get('generated') or x.get('accepted') is None or not 0<=x['accepted']<=x['generated'] for x in counts):
        return {'promote':False,'reason':'missing_mtp_counts'}
    drop=100*(counts[0]['accepted']/counts[0]['generated']-counts[1]['accepted']/counts[1]['generated'])
    ok=(changes['batch_wall_s']<=-5+1e-9 and changes['ttft_mean_s']<=5+1e-9
        and changes['ttft_p95_s']<=5+1e-9 and changes['mean_decode']>=-5-1e-9 and drop<10-1e-9)
    near=any(abs(changes[k]-limit)<=2+1e-9 for k,limit in
             [('batch_wall_s',-5),('ttft_mean_s',5),('ttft_p95_s',5),('mean_decode',-5)])
    return {'promote':ok,'reason':'qualified' if ok else ('mtp_hold' if drop>=10-1e-9 else 'regression_or_no_gain'),
            'changes_pct':changes,'mtp_drop_pp':drop,'bounded_recheck_eligible':near,
            'max_additional_runs_per_profile':1}

def summarize_gpu(samples):
    """Observed sample statistics; loaded means utilization > 0, not full load."""
    result={}
    for device in (0,1):
        result[str(device)]={}
        for phase in ('idle','loaded'):
            selected=[g for row in samples for g in row.get('gpu',[])
                      if g['index']==device and g['metrics']['utilization_pct']['value'] is not None
                      and (g['metrics']['utilization_pct']['value']>0)==(phase=='loaded')]
            stats={}
            for field in ('sm_clock_mhz','power_w','memory_used_mib','temperature_c','utilization_pct'):
                vals=[g['metrics'][field]['value'] for g in selected if g['metrics'][field]['value'] is not None]
                stats[field]={'mean':sum(vals)/len(vals) if vals else None,
                              'p95':percentile95(vals),'peak':max(vals) if vals else None,
                              'samples':len(vals),'unavailable_reason':None if vals else 'No valid samples in this phase'}
            result[str(device)][phase]=stats
    paired=[]
    for row in samples:
        by_index={g['index']:g for g in row.get('gpu',[])}
        vals=[by_index[i]['metrics']['utilization_pct']['value'] for i in (0,1)] if set(by_index)=={0,1} else None
        paired.append({'t_s':row['t_s'],'utilization':vals})
    return {'devices':result,'overlap_proxy':overlap_proxy(paired),
            'sampling_definition':'0.5s target; observed gaps and coverage retained; averages/p95 are sample statistics'}


def confirmation_candidates(model, baseline, candidates, phase):
    """Bounded planning only. Never executes a confirmation or names a winner."""
    if phase not in ('9.2','9.3'):
        raise ValueError('Only split/batch confirmation planning is in scope')
    if baseline.get('comparison_key',{}).get('model')!=model:
        raise ValueError('Wrong model baseline')
    valid=[c for c in candidates if promotion(baseline,c)['promote']]
    if phase=='9.2':
        # Caller must attach independently reviewed benefit for BOTH models.
        valid=[c for c in valid if c.get('both_models_row_benefit') is True]
    valid.sort(key=lambda c:c['metrics']['batch_wall_s'])
    return [{'experiment_id':c['experiment_id'],'confirmation_context':32768,
             'final_capacity_preserved':False,
             'finalist_requirement':65536 if model=='ornith' else 32768}
            for c in valid[:2 if phase=='9.3' else 1]]


def recheck_plan(baseline,candidate,history):
    """One paired recheck per finalist. The caller preserves this decision ledger."""
    gate=promotion(baseline,candidate)
    if not gate.get('bounded_recheck_eligible'):
        return {'runs':[],'reason':'Not an ambiguous near-threshold finalist'}
    identity=[baseline['experiment_id'],candidate['experiment_id']]
    if any(row.get('pair')==identity for row in history):
        return {'runs':[],'reason':'Recheck already allocated; retain baseline unless confirmation passes'}
    return {'pair':identity,'runs':['baseline_once','candidate_once'],
            'reason':'Record this allocation before executing; at most one pair'}


def validate_bundle(root):
    manifest=json.loads((root/'bundle.json').read_text())
    for name,digest in manifest['files'].items():
        p=(root/name).resolve()
        if not p.is_relative_to(root.resolve()) or sha(p)!=digest:
            raise ValueError('Bundle hash mismatch')
    models=json.loads((root/'manifest.json').read_text())['models']
    for model in models:
        for tier in (16,32):
            folder=root/'workloads'/f'{model}-{tier}k'
            work=validate_workload(folder,models[model])
            receipt=json.loads((folder/'receipt.json').read_text())
            if work['model']!=model or receipt['corpus_sha256']!=sha(root/'corpus.txt'):
                raise ValueError('Corpus/model binding mismatch')
    return manifest

def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('command',choices=['prepare','inspect','validate','plan'])
    p.add_argument('--bundle',type=Path,required=True)
    a=p.parse_args()
