#!/usr/bin/env python3
"""Download and verify Ornith-1.5-35B-A3B-NVFP4 on p520-llm for WBS 7.5.

Safely uses huggingface_hub snapshot_download with explicit revision pinning,
verifies file hashes, and validates directory structure.
"""
import hashlib
import json
import os
from pathlib import Path
import socket
import sys

TARGET_REPO = "ornith-ai/Ornith-1.5-35B-A3B-NVFP4"
TARGET_REVISION = "94e431d9cc47fa1986a7a1a4e9a80f7f118b03aa"
TARGET_DIR = Path("/srv/models/p520-lab-candidates/ornith-nvfp4/94e431d9cc47fa1986a7a1a4e9a80f7f118b03aa")

EXPECTED_SHARDS = {
    "model-00001-of-00003.safetensors": {
        "bytes": 10005851848,
        "sha256": "648fe83171485f4be03ea58d86089e088c94c2a3dc88922233f9002f30d8bc8b",
    },
    "model-00002-of-00003.safetensors": {
        "bytes": 10006454416,
        "sha256": "cb5c5978721a1e87406ae68f1cd5a855326e40ff8bc13832644c392115336987",
    },
    "model-00003-of-00003.safetensors": {
        "bytes": 3408113436,
        "sha256": "8303cef7d375021d69dcafc60d3fad5f8186995b18b0db5e2a609aadeb8a4f51",
    },
}


def main():
    if socket.gethostname() != "p520-llm":
        raise SystemExit("Refusing download: target must be p520-llm")

    TARGET_DIR.parent.mkdir(parents=True, exist_ok=True)

    free = os.statvfs(TARGET_DIR.parent)
    free_bytes = free.f_bavail * free.f_frsize
    total_needed = sum(v["bytes"] for v in EXPECTED_SHARDS.values()) + 10 * (1024**3)
    if free_bytes < total_needed:
        raise SystemExit(f"Insufficient disk space: {free_bytes / (1024**3):.1f} GiB free, need {total_needed / (1024**3):.1f} GiB")

    print(f"Downloading {TARGET_REPO} revision {TARGET_REVISION} to {TARGET_DIR}...", flush=True)
    from huggingface_hub import snapshot_download

    snapshot_download(
        repo_id=TARGET_REPO,
        revision=TARGET_REVISION,
        local_dir=str(TARGET_DIR),
        local_dir_use_symlinks=False,
        resume_download=True,
    )

    print("Verifying file integrity against SHA256 hashes...", flush=True)
    verified = {}
    for filename, meta in EXPECTED_SHARDS.items():
        filepath = TARGET_DIR / filename
        if not filepath.exists():
            raise SystemExit(f"Missing expected shard: {filepath}")
        actual_size = filepath.stat().st_size
        if actual_size != meta["bytes"]:
            raise SystemExit(f"Size mismatch on {filename}: actual {actual_size}, expected {meta['bytes']}")

        digest = hashlib.sha256()
        with filepath.open("rb") as f:
            while chunk := f.read(8 * 1024 * 1024):
                digest.update(chunk)
        actual_sha = digest.hexdigest()
        if actual_sha != meta["sha256"]:
            raise SystemExit(f"SHA256 mismatch on {filename}: actual {actual_sha}, expected {meta['sha256']}")

        verified[filename] = {
            "bytes": actual_size,
            "sha256": actual_sha,
            "status": "VERIFIED",
        }
        print(f"Verified {filename}: {actual_size / (1024**3):.2f} GiB OK", flush=True)

    result = {
        "repo": TARGET_REPO,
        "revision": TARGET_REVISION,
        "target_dir": str(TARGET_DIR),
        "shards": verified,
        "status": "ALL_VERIFIED",
    }
    print(json.dumps(result, indent=2), flush=True)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Offline text preparation only. No network, tokenizer, inference or server access."""
import argparse
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def sha(data):
    return hashlib.sha256(data).hexdigest()


def canonical(value):
    return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2) + '\n').encode('utf-8')


def prepare(concurrency=1, seed=520, purpose='representative', copies=1,
            completion_tokens=1024):
    if not isinstance(concurrency, int) or not 1 <= concurrency <= 10:
        raise ValueError('concurrency must be 1..10')
    if type(seed) is not int or not 0 <= seed <= 2**32 - 1:
        raise ValueError('seed must be an unsigned 32-bit integer')
    if purpose not in ('representative', 'capacity'):
        raise ValueError('unknown purpose')
    if not 1 <= copies <= 128 or (purpose == 'representative' and copies != 1):
        raise ValueError('copies 1..128; repetition is allowed only for capacity')
    if type(completion_tokens) is not int or not 1 <= completion_tokens <= 4096:
        raise ValueError('completion_tokens must be 1..4096')
    manifest = json.loads((ROOT / 'workloads/sources.json').read_text())
    sources = {}
    for item in manifest['files']:
        path = ROOT / item['path']
        data = path.read_bytes()
        if sha(data) != item['sha256'] or len(data) != item['size_bytes']:
            raise ValueError(f'source hash/size mismatch: {item["path"]}')
        sources[item['path']] = data.decode('utf-8')
    corpus = sources['workloads/corpus/harbor-ops-v1.md']
    task = sources['workloads/task-v1.txt']
    requests = []
    for index in range(concurrency):
        # Each C1/C5/C10 prefix uses the same IDs and text. Stable across Python versions.
        nonce = sha(f'harbor-v1:{seed}:{index}'.encode())[:16]
        user = f'Review reference: {nonce}\n\n{task}\n<dossier>\n'
        user += '\n'.join(f'Volume {i + 1}\n{corpus}' for i in range(copies))
        user += '\n</dossier>\n'
        requests.append({
            'request_id': f'req-{index + 1:02d}',
            'raw_prompt': user, 'raw_prompt_sha256': sha(user.encode()),
            'requested_completion_tokens': completion_tokens,
        })
    return {
        'schema_version': '1.0', 'workload_id': 'harbor-ops-v1',
        'stage': 'text_prepared', 'purpose': purpose, 'concurrency': concurrency,
        'seed': seed, 'corpus_copies': copies,
        'source_manifest_sha256': sha((ROOT / 'workloads/sources.json').read_bytes()),
        'builder_sha256': sha(Path(__file__).read_bytes()),
        'sampling': {'temperature': 0, 'top_p': 1, 'seed': seed},
        'requests': requests,
    }


def write_new(path, value):
    # A prepared file has no timestamps or local absolute paths; bytes are replayable.
    with Path(path).open('xb') as stream:
        stream.write(canonical(value))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--concurrency', type=int, choices=(1, 2, 3, 4, 5, 10), default=1)
    parser.add_argument('--seed', type=int, default=520)
    parser.add_argument('--purpose', choices=('representative', 'capacity'), default='representative')
    parser.add_argument('--copies', type=int, default=1)
    parser.add_argument('--completion-tokens', type=int, default=1024)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    try:
        value = prepare(args.concurrency, args.seed, args.purpose, args.copies, args.completion_tokens)
        write_new(args.output, value)
    except (ValueError, FileExistsError) as exc:
        parser.error(str(exc))


if __name__ == '__main__':
    main()

