CANDIDATES={
 'control':dict(quant='Q5KM',pool=131072,mtp=2,path='/srv/models/qwen3.8-27b/Qwen3.8-27B-Q5_K_M.gguf',sha='e731e180460b906f373294a4e2de10541e80ee676af7f8c949a84dbb6ed3caa8'),
 'q5km-target':dict(quant='Q5KM',pool=196608,mtp=0,path='/srv/models/qwen3.8-27b/Qwen3.8-27B-Q5_K_M.gguf',sha='e731e180460b906f373294a4e2de10541e80ee676af7f8c949a84dbb6ed3caa8'),
 'q5ks-target':dict(quant='Q5KS',pool=262144,mtp=0,path='/srv/models/p520-lab-candidates/qwen3.8/125a02af4987b57c7deb88d7f2ec58a5725c07c0/Qwen3.8-27B-Q5_K_S.gguf',sha='166789044f55f328e230fe2b723c7db06537bcec71d19146e88e0ef592130f8d'),
 'q4km-target':dict(quant='Q4KM',pool=262144,mtp=0,path='/srv/models/qwen3.8-27b/Qwen3.8-27B-Q4_K_M-bartowski.gguf',sha='e103abf9d914d1d7b2f2592f055f2759a71195c350a01c135f71aaae86bca52b')}

def http(path,payload=None,timeout=10):
    req=urllib.request.Request(BASE+path,data=None if payload is None else json.dumps(payload).encode(),headers={'Content-Type':'application/json'})
    with urllib.request.urlopen(req,timeout=timeout) as r:return json.load(r)

def policy(data):
    # Phase 9 accepted historical 1050 as well. U requires exactly the current 1200 policy.
    latest=[x for x in data['application'].splitlines() if 'GPU clocks set to' in x][-2:]
    return (data['policy_valid'] and data['service'].count('-lgc 135,1200')==2
            and len(latest)==2 and all('gpuClkMin 135, gpuClkMax 1200' in x for x in latest))

def launch(cfg,exp):
    cmd=['docker','create','--name','p520-u2-'+exp.lower(),'--label','p520.project=p520-inference-lab',
      '--label','p520.experiment='+exp,'--read-only','--tmpfs','/tmp:rw,size=4g','--gpus','all',
      '-e','GGML_CUDA_P2P=1','-p','127.0.0.1:8019:8080','-v',cfg['path']+':/model.gguf:ro',
      '--entrypoint','timeout',IMAGE,'--signal=TERM','--kill-after=30s','7500s','llama-server',
      '-m','/model.gguf','-ngl','99','--split-mode','layer','--tensor-split','1,1','-fa','on',
      '-ctk','q8_0','-ctv','q8_0','-c',str(cfg['pool']),'-b','2048','-ub','512',
      '--parallel','4','--kv-unified','--kv-unified-per-slot','65536','--no-context-shift',
      '--no-cache-prompt','--cache-ram','0','--cache-reuse','0','--metrics','--slots','--jinja',
      '--reasoning','on','--reasoning-budget','512','--reasoning-format','deepseek',
      '--host','0.0.0.0','--port','8080']
    if cfg['mtp']:cmd+=['--spec-type','draft-mtp','--spec-draft-n-max','2']
    return cmd

def request(task,work,out,origin):
    messages=[{'role':'system','content':'You are a careful coding assistant. Follow the project boundary and requested output contract. Reason briefly before the final answer.'},
              {'role':'user','content':task['prompt']}]
    common={'messages':messages,'chat_template_kwargs':{'enable_thinking':True}}
    if task.get('tools'):common.update(tools=task['tools'],tool_choice='auto',parallel_tool_calls=False)
    rendered=http('/apply-template',common)['prompt']
    raw=http('/tokenize',{'content':'\n'.join(m['content'] for m in messages),'add_special':False})['tokens']
    tokens=http('/tokenize',{'content':rendered,'add_special':True})['tokens']
    receipt={'raw_tokens':len(raw),'post_template_tokens':len(tokens),'rendered_prompt':rendered,
             'tokens_sha256':hashlib.sha256(json.dumps(tokens).encode()).hexdigest()}
    atomic_json(out/(task['id']+'-receipt.json'),receipt)
    if len(tokens)+work['max_tokens']+40>8192:raise ValueError('Task exceeds frozen 8K budget')
    payload={**common,'model':'qwen','temperature':0,'seed':520,'max_tokens':work['max_tokens'],
             'stream':True,'stream_options':{'include_usage':True},'cache_prompt':False}
    atomic_json(out/(task['id']+'-request.json'),payload)
    start=time.monotonic();first=None;calls={};usage=None;finish=None;content='';reasoning='';timings=None
    req=urllib.request.Request(BASE+'/v1/chat/completions',data=json.dumps(payload).encode(),headers={'Content-Type':'application/json'})
    # Outer bounded_call enforces a hard 300s deadline even if peer sends partial data forever.
    with urllib.request.urlopen(req,timeout=120) as r,(out/(task['id']+'-stream.jsonl')).open('x') as log:
        for line in r:
            now=time.monotonic();line=line.decode().strip()
            if not line.startswith('data:'):continue
            if line[5:].strip()=='[DONE]':break
            item=json.loads(line[5:]);log.write(json.dumps({'at_s':now-origin,'response':item})+'\n');log.flush()
            if item.get('usage'):usage=item['usage']
            if item.get('timings'):timings=item['timings']
            for choice in item.get('choices',[]):
                d=choice.get('delta',{})
                if d.get('content') or d.get('reasoning_content') or d.get('tool_calls'):
                    if first is None:first=now
                content+=d.get('content') or '';reasoning+=d.get('reasoning_content') or ''
                for call in d.get('tool_calls',[]):
                    v=calls.setdefault(call['index'],{'id':'','type':'function','function':{'name':'','arguments':''}})
                    if call.get('id'):v['id']=call['id']
                    for key in ('name','arguments'):v['function'][key]+=call.get('function',{}).get(key) or ''
                if choice.get('finish_reason'):finish=choice['finish_reason']
            if first is None and now-start>120:raise TimeoutError('TTFT deadline')
    return {'task_id':task['id'],'kind':task['kind'],'content':content,'reasoning':reasoning,
            'tool_calls':list(calls.values()),'finish_reason':finish,'usage':usage,'native_timings':timings,
            'ttft_s':None if first is None else first-start,'ttft_kind':'first content/reasoning/tool delta; chunks are not tokens',
            'wall_s':time.monotonic()-start,'submit_s':start-origin,'raw_tokens':len(raw),'post_template_tokens':len(tokens),
            'requested_output_tokens':work['max_tokens'],'token_count_matches':bool(usage and usage.get('prompt_tokens')==len(tokens))}

def validate_oracles(bundle):
    work=json.loads((bundle/'quality-v1.json').read_text());rows=[]
    for t in work['tasks']:
        if t['kind']=='coding':
            good=run_code(t['reference'],t['tests']);bad=run_code(t['bug'],t['tests'])
            rows.append({'task':t['id'],'reference':good,'bug':bad})
    return {'pass':len(rows)==8 and all(x['reference']['pass'] and not x['bug']['pass'] for x in rows),'rows':rows}

def execute(bundle,key,exp):
    cfg=CANDIDATES[key];work=json.loads((bundle/'quality-v1.json').read_text())
    ROOT.mkdir(exist_ok=True,parents=True)
    with (ROOT/'experiment.lock').open('a+') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        out=ROOT/'runs'/exp;out.mkdir(parents=True,exist_ok=False)
        recorded=None;stop=threading.Event();threads=[];results=[]
        result={'experiment_id':exp,'candidate':key,'evidence_kind':'measurement','verdict':'INCONCLUSIVE'}
        origin=time.monotonic();before=None
        def checkpoint(phase):atomic_json(out/'progress.json',{'phase':phase,'experiment_id':exp,'runner':identity(os.getpid()),'container':recorded,'completed':len(results),'bundle':str(bundle),'time':time.time()})
        checkpoint('prepared')
        try:
            before=inspect_host();atomic_json(out/'before.json',before)
            if not policy(before):raise ValueError('1200 policy not established')
            require_idle(before)
            if command(['docker','image','inspect',IMAGE,'--format','{{.Id}}']).strip()!=IMAGE:raise ValueError('Image mismatch')
            with open(cfg['path'],'rb') as f:
                if hashlib.file_digest(f,'sha256').hexdigest()!=cfg['sha']:raise ValueError('Model SHA mismatch')
            atomic_json(out/'config.json',cfg)
            fresh=inspect_host();require_idle(fresh)
            if not policy(fresh):raise ValueError('policy changed before start')
            cmd=launch(cfg,exp);atomic_json(out/'launch.json',cmd)
            cid=command(cmd,timeout=30).strip();recorded=container_identity(cid);checkpoint('created')
            command(['docker','start',cid],timeout=30);recorded=container_identity(cid);checkpoint('starting')
            for kind in ('gpu','slots','scheduler'):
                thread=threading.Thread(target=sample_loop,args=(kind,out,origin,stop),daemon=True);thread.start();threads.append(thread)
            start=time.monotonic()
            while True:
                if time.monotonic()-start>300:raise TimeoutError('startup timeout')
                state=json.loads(command(['docker','inspect',cid]))[0]['State']
                if not state['Running']:raise RuntimeError('FAIL_STARTUP: server exited')
                try:
                    if http('/health')['status']=='ok':break
                except Exception:pass
                time.sleep(1)
            atomic_json(out/'startup.json',{'seconds':time.monotonic()-start,'health':'PASS'})
            atomic_json(out/'props.json',http('/props'))
            for task in work['tasks']:
                p=inspect_host()
                if not policy(p) or p['cpu_policy']!=before['cpu_policy']:raise ValueError('Hardware policy changed')
                atomic_json(out/(task['id']+'-policy.json'),{k:p[k] for k in ('gpus','cpu_policy','governors','no_turbo','policy_valid')})
                checkpoint('measuring:'+task['id'])
                row=bounded_call(request,args=(task,work,out,origin),deadline=time.monotonic()+300,cleanup_grace_s=5,record=lambda phase,receipt: atomic_json(out/(task['id']+'-worker.json'),{'phase':phase,'receipt':receipt}))
                results.append(row);atomic_json(out/(task['id']+'-result.json'),row)
                if not row['token_count_matches']:raise ValueError('Template receipt differs from server prompt usage')
                if row['ttft_s'] is None or row['ttft_s']>120:raise TimeoutError('TTFT deadline exceeded')
            result['postflight_health']=http('/health')
            result['measurement_complete']=True
        except BaseException as e:
            result['error']=str(e)
            result['verdict']='FAIL_TIMEOUT' if isinstance(e,TimeoutError) or getattr(e,'verdict',None)=='FAIL_TIMEOUT' else 'INCONCLUSIVE'
            if 'FAIL_STARTUP' in str(e):result['verdict']='FAIL_STARTUP'
        finally:
            stop.set()
            for t in threads:t.join(timeout=5)
            if recorded:
                logs=subprocess.run(['docker','logs',recorded['id']],capture_output=True,text=True,timeout=15)
                (out/'server.log').write_text(logs.stdout+logs.stderr)
                try:cleanup(recorded,exp);result['cleanup_verified']=True
                except Exception as e:result['cleanup_error']=str(e)
            after=inspect_host();atomic_json(out/'after.json',after)
            result['hardware_preserved']=bool(before) and policy(after) and after['cpu_policy']==before['cpu_policy']
            # CPU code evaluation after the timed inference and GPU server cleanup.
            for row in results:
                task=next(t for t in work['tasks'] if t['id']==row['task_id'])
                row['score']=score(task,row);atomic_json(out/(row['task_id']+'-result.json'),row)
            result.update(requests=results,elapsed_s=time.monotonic()-origin,quality_pass_count=sum(r['score']['pass'] for r in results))
            if result.get('measurement_complete') and result.get('cleanup_verified') and result['hardware_preserved']:
                result['verdict']='PASS' if result['quality_pass_count']>=16 else 'FAIL_OUTPUT'
                result['reason']='absolute screening floor only; paired comparison pending'
            atomic_json(out/'result.json',result);checkpoint('finished')
            atomic_json(out/'exit.json',{'finished':True,'verdict':result['verdict']})

def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--bundle',type=Path,required=True);p.add_argument('--bundle-sha256',required=True)
    p.add_argument('--candidate',choices=CANDIDATES);p.add_argument('--experiment-id');p.add_argument('--validate-oracles',action='store_true');a=p.parse_args()
    if platform.node()!='p520-llm':raise ValueError('Wrong host')
    manifest=a.bundle/'bundle.json'
    if hashlib.sha256(manifest.read_bytes()).hexdigest()!=a.bundle_sha256:raise ValueError('Bundle manifest SHA mismatch')
    for name,digest in json.loads(manifest.read_text())['files'].items():
        if hashlib.sha256((a.bundle/name).read_bytes()).hexdigest()!=digest:raise ValueError('Bundle file mismatch '+name)
    if a.validate_oracles:
        result=validate_oracles(a.bundle);atomic_json(a.bundle/'oracle-validation.json',result);print(json.dumps(result));return
    if not a.candidate or not a.experiment_id:p.error('candidate and experiment ID required')
    import re
    cfg=CANDIDATES[a.candidate]
    if not re.fullmatch('EXP-Q38-LLAMA-'+cfg['quant']+'-Q8-C1-8K-[0-9]{3}',a.experiment_id):raise ValueError('ID mismatch')
    def interrupted(sig,frame):raise InterruptedError('supervisor signal '+str(sig))
    signal.signal(signal.SIGTERM,interrupted)
    execute(a.bundle,a.candidate,a.experiment_id)
if __name__=='__main__':main()

#!/usr/bin/env python3
"""Bounded read-only P520 sampling; runtime scheduler mappings are external."""
import argparse
import csv
from datetime import datetime, timezone
import io
import math
import os
import stat
from pathlib import Path
import platform
import subprocess
import time

from benchmark_runner import atomic_json, encoded, read_json, process_identity

GPU_FIELDS = {
    'memory_used_mib': 'memory.used', 'power_w': 'power.draw',
    'temperature_c': 'temperature.gpu', 'sm_clock_mhz': 'clocks.sm',
    'utilization_pct': 'utilization.gpu', 'power_limit_w': 'power.limit',
}
COMMAND = ['nvidia-smi', '--query-gpu=uuid,index,' + ','.join(GPU_FIELDS.values())
           + ',persistence_mode', '--format=csv,noheader,nounits']
SCHEDULER_FIELDS = ('running_requests', 'waiting_requests', 'kv_used_fraction')


def metric(value=None, reason=None):
    return {'value': value, 'unavailable_reason': reason}


def number(raw, maximum=None, integer=False):
    try:
        value = float(raw)
        if not math.isfinite(value) or value < 0 or (maximum is not None and value > maximum):
            raise ValueError('out of range')
        if integer and not value.is_integer():
            raise ValueError('not an integer')
        return metric(int(value) if integer else value)
    except (ValueError, TypeError):
        return metric(reason='unavailable or invalid source value: ' + str(raw)[:100])


def parse_gpu(text):
    rows = []
    seen = set()
    for row in csv.reader(io.StringIO(text)):
        if len(row) != 9:
            raise ValueError('unexpected NVIDIA CSV column count')
        row = [v.strip() for v in row]
        uuid, index = row[:2]
        if not uuid.startswith('GPU-') or uuid in seen or not index.isdigit():
            raise ValueError('invalid or duplicate GPU identity')
        seen.add(uuid)
        values = {name: number(raw, 100 if name == 'utilization_pct' else None)
                  for name, raw in zip(GPU_FIELDS, row[2:8])}
        values['persistence_enabled'] = (metric(row[8] == 'Enabled')
                                        if row[8] in ('Enabled', 'Disabled') else
                                        metric(reason='persistence field unavailable'))
        rows.append({'uuid': uuid, 'index': int(index), 'metrics': values})
    if len(rows) != 2 or len({r['index'] for r in rows}) != 2:
        raise ValueError('expected two distinct P520 GPUs')
    return rows


def read_gpu(timeout):
    result = subprocess.run(COMMAND, capture_output=True, text=True, timeout=timeout,
                            check=True)
    return parse_gpu(result.stdout)


def scheduler_snapshot(path, max_age_s, now=None):
    """Read a bounded normalized snapshot; retain freshness and source provenance."""
    missing = {key: metric(reason='no scheduler snapshot configured') for key in SCHEDULER_FIELDS}
    result = {'source': None, 'observed_at_utc': None, 'age_s': None, 'metrics': missing}
    if path is None:
        return result
    try:
        fd = os.open(path, os.O_RDONLY | os.O_NONBLOCK | os.O_NOFOLLOW)
        with os.fdopen(fd, 'rb') as stream:
            if not stat.S_ISREG(os.fstat(stream.fileno()).st_mode):
                raise ValueError('scheduler snapshot must be a regular file')
            raw = stream.read(65537)
        if len(raw) > 65536:
            raise ValueError('scheduler snapshot exceeds 64 KiB')
        obj = read_json(raw)
        if set(obj) != {'source', 'observed_at_utc', *SCHEDULER_FIELDS}:
            raise ValueError('unexpected scheduler snapshot fields')
        if not isinstance(obj['source'], str) or not obj['source'].strip():
            raise ValueError('scheduler source required')
        observed = datetime.fromisoformat(obj['observed_at_utc'].replace('Z', '+00:00'))
        if observed.utcoffset() is None:
            raise ValueError('scheduler timestamp must include timezone')
        age = ((now or datetime.now(timezone.utc)) - observed).total_seconds()
        result.update(source=obj['source'], observed_at_utc=obj['observed_at_utc'], age_s=age)
        if age < 0 or age > max_age_s:
            raise ValueError('scheduler snapshot stale or in future; clock alignment required')
        for key in SCHEDULER_FIELDS:
            value = obj[key]
            result['metrics'][key] = (number(value, 1 if key == 'kv_used_fraction' else None,
                                            key != 'kv_used_fraction')
                                      if type(value) in (int, float) else
                                      metric(reason='scheduler metric missing or not numeric'))
    except (OSError, ValueError, TypeError, KeyError, AttributeError) as exc:
        result['metrics'] = {key: metric(reason=str(exc)) for key in SCHEDULER_FIELDS}
    return result


def summarize(samples, interval_s, duration_s):
    """Observed sample maxima only; never interpolate across gaps or GPU UUIDs."""
    gpu_ids = sorted({g['uuid'] for sample in samples for g in sample['gpus']})
    gpu_summary = {}
    for uuid in gpu_ids:
        metrics = {}
        for key in (*GPU_FIELDS, 'persistence_enabled'):
            values = [g['metrics'][key]['value'] for s in samples for g in s['gpus']
                      if g['uuid'] == uuid and g['metrics'][key]['value'] is not None]
            metrics[key] = {'observed_max': metric(max(values)) if values else
                            metric(reason='no valid samples'), 'valid_samples': len(values),
                            'missing_samples': len(samples) - len(values)}
        gpu_summary[uuid] = metrics
    scheduled = math.ceil(duration_s / interval_s)
    return {'attempted_samples': len(samples), 'scheduled_samples': scheduled,
            'skipped_slots': max(0, scheduled - len(samples)),
            'gpu_query_failures': sum(s['gpu_error'] is not None for s in samples),
            'gpu_peaks': gpu_summary,
            'gpu_inventory_reason': None if gpu_ids else 'no successful GPU inventory',
            'scheduler_peaks': {key: peak_scheduler(samples, key) for key in SCHEDULER_FIELDS},
            'limitation': 'sample maxima can miss between-sample peaks; no interpolation; '
                          'scheduler samples do not prove all-request overlap'}


def peak_scheduler(samples, key):
    values = [s['scheduler']['metrics'][key]['value'] for s in samples
              if s['scheduler']['metrics'][key]['value'] is not None]
    return {'observed_max': metric(max(values)) if values else metric(reason='no valid samples'),
            'valid_samples': len(values), 'missing_samples': len(samples) - len(values)}


def collect(output, *, target_host, phase, duration_s, interval_s=1, query_timeout_s=2,
            scheduler_path=None, scheduler_max_age_s=2, gpu_reader=read_gpu,
            clock=time.monotonic, sleep=time.sleep):
    if target_host != 'p520-llm' or platform.node() != target_host:
        raise ValueError('collector must execute on explicitly selected p520-llm')
    for value in (duration_s, interval_s, query_timeout_s, scheduler_max_age_s):
        if not math.isfinite(value) or value <= 0:
            raise ValueError('durations must be finite and positive')
    if duration_s > 3600 or interval_s < 0.1 or duration_s / interval_s > 36000:
        raise ValueError('bounded collector permits at most 1 hour and 36000 slots, interval >=0.1s')
    if phase not in ('idle', 'warmup', 'measurement', 'after'):
        raise ValueError('unknown workload phase')
    output = Path(output)
    output.mkdir(parents=True, exist_ok=False)
    start = clock()
    manifest = {'schema_version': '1.0', 'target_host': target_host, 'phase': phase,
                'started_at_utc': datetime.now(timezone.utc).isoformat(),
                'monotonic_origin_s': start, 'process': process_identity(),
                'interval_s': interval_s, 'duration_s': duration_s,
                'query_timeout_s': query_timeout_s, 'gpu_command': COMMAND,
                'scheduler_path': str(scheduler_path) if scheduler_path else None,
                'scheduler_max_age_s': scheduler_max_age_s,
                'policy_scope': 'observations only; clock range/service and CPU policy require '
                                'separate read-only preflight and after evidence'}
    atomic_json(output / 'manifest.json', manifest)
    samples = []
    status = 'completed'
    slot = 0
    try:
        with (output / 'samples.jsonl').open('xb') as stream:
            while slot * interval_s < duration_s:
                sleep(max(0, start + slot * interval_s - clock()))
                offset = clock() - start
                if offset >= duration_s:
                    break
                sample = {'slot': slot, 'phase': phase, 'scheduled_offset_s': slot * interval_s,
                          'offset_s': offset, 'observed_at_utc': datetime.now(timezone.utc).isoformat(),
                          'gpus': [], 'gpu_error': None}
                try:
                    sample['gpus'] = gpu_reader(min(query_timeout_s, duration_s - offset))
                except (OSError, ValueError, subprocess.SubprocessError) as exc:
                    sample['gpu_error'] = type(exc).__name__ + ': ' + str(exc)[:500]
                sample['scheduler'] = scheduler_snapshot(scheduler_path, scheduler_max_age_s)
                sample['finished_offset_s'] = clock() - start
                stream.write(encoded(sample).replace(b'\n', b'') + b'\n')
                stream.flush()
                os.fsync(stream.fileno())
                samples.append(sample)
                slot = max(slot + 1, math.ceil((clock() - start) / interval_s))
    except KeyboardInterrupt:
        status = 'interrupted'
    summary = summarize(samples, interval_s, duration_s)
    summary.update(schema_version='1.0', status=status, elapsed_s=clock() - start)
    atomic_json(output / 'summary.json', summary)
    return summary


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--target-host', required=True, choices=['p520-llm'])
    parser.add_argument('--output', required=True, type=Path)
    parser.add_argument('--phase', required=True, choices=['idle', 'warmup', 'measurement', 'after'])
    parser.add_argument('--duration-s', required=True, type=float)
    parser.add_argument('--interval-s', default=1, type=float)
    parser.add_argument('--query-timeout-s', default=2, type=float)
    parser.add_argument('--scheduler-path', type=Path)
    parser.add_argument('--scheduler-max-age-s', default=2, type=float)
    args = vars(parser.parse_args())
    try:
        result = collect(**args)
    except (ValueError, OSError) as exc:
        parser.exit(2, str(exc) + '\n')
    return 130 if result['status'] == 'interrupted' else 0


if __name__ == '__main__':
    raise SystemExit(main())

#!/usr/bin/env python3
"""Track U quality scoring. Generated code runs only in a restricted CPU container on P520."""
import json
import platform
import subprocess
import uuid

IMAGE='sha256:461d786f1281101c547798c44c494feb2c498921cff516e7580531f68187aa43'
# No models, repository, home directories, sockets, credentials or network are exposed.
SANDBOX=['docker','run','--rm','-i','--network','none','--read-only','--cap-drop','ALL',
 '--security-opt','no-new-privileges','--user','65534:65534','--pids-limit','32',
 '--memory','256m','--cpus','1','--tmpfs','/tmp:rw,nosuid,noexec,size=16m',
 '-v','/usr:/usr:ro','-v','/lib:/lib:ro','-v','/lib64:/lib64:ro',
 '--entrypoint','/usr/bin/python3',IMAGE,'-I','-c',
 'import json,sys; p=json.load(sys.stdin); ns={}; exec(compile(p["source"],"candidate.py","exec"),ns); exec(compile(p["tests"],"oracle.py","exec"),ns); print("U2_ORACLE_PASS")']

def run_code(source,tests):
    if platform.node()!='p520-llm':raise ValueError('Code evaluation must run on p520-llm in Docker')
    name='p520-u2-eval-'+uuid.uuid4().hex
    cmd=SANDBOX[:2]+['--name',name,'--label','p520.project=p520-inference-lab','--label','p520.role=u2-evaluator']+SANDBOX[2:]
    try:
        p=subprocess.run(cmd,input=json.dumps({'source':source,'tests':tests}),capture_output=True,text=True,timeout=15)
        return {'pass':p.returncode==0 and p.stdout.rstrip().endswith('U2_ORACLE_PASS'),
                'exit_code':p.returncode,'stdout':p.stdout[-4000:],'stderr':p.stderr[-4000:]}
    except subprocess.TimeoutExpired:
        # UUID name was created by this call only; verify labels before cleanup.
        p=subprocess.run(['docker','inspect',name],capture_output=True,text=True,timeout=5)
        if p.returncode==0:
            info=json.loads(p.stdout)[0]
            if info['Config']['Labels'].get('p520.role')=='u2-evaluator':
                subprocess.run(['docker','stop','-t','1',info['Id']],capture_output=True,timeout=5)
        return {'pass':False,'reason':'oracle timeout'}

def score(task,result):
    if result.get('finish_reason') not in ('stop','tool_calls'):
        return {'pass':False,'reason':'missing natural completion or output limit'}
    try:
        if task['kind']=='tool':
            calls=result.get('tool_calls',[])
            if len(calls)!=1:return {'pass':False,'reason':'expected exactly one tool call'}
            got={'name':calls[0]['function']['name'],'arguments':json.loads(calls[0]['function']['arguments'])}
            return {'pass':got==task['answer'],'actual':got,'expected':task['answer']}
        got=json.loads(result['content'])
        if task['kind']=='reasoning':return {'pass':got==task['answer'],'actual':got,'expected':task['answer']}
        if set(got)!= {'source'} or not isinstance(got['source'],str):return {'pass':False,'reason':'invalid source object'}
        return run_code(got['source'],task['tests'])
    except (ValueError,KeyError,TypeError) as e:return {'pass':False,'reason':str(e)}

def compare(tasks,baseline,candidate):
    b={r['task_id']:r['score']['pass'] for r in baseline}
    c={r['task_id']:r['score']['pass'] for r in candidate}
    ids={t['id'] for t in tasks}
    if set(b)!=ids or set(c)!=ids:return {'verdict':'INCONCLUSIVE','reason':'missing/extra tasks'}
    base=sum(b.values());n=sum(c.values())
    regressions=[t['id'] for t in tasks if t['critical'] and b[t['id']] and not c[t['id']]]
    if base<16:return {'verdict':'INCONCLUSIVE','reason':'Q5KM anchor below 80% floor','baseline_pass':base}
    return {'verdict':'PASS' if n>=16 and base-n<=1 and not regressions else 'FAIL_OUTPUT',
            'baseline_pass':base,'candidate_pass':n,'total':20,'loss_percentage_points':(base-n)*5,
            'new_critical_failures':regressions}

import sys
from pathlib import Path
import unittest
sys.path.insert(0,str(Path(__file__).resolve().parents[1]/'scripts'))
from llama_fixed_slot import validate_native, overlap

class NativeEvidenceTests(unittest.TestCase):
    def test_native_counts_and_truncation_are_authoritative(self):
        reply={'text':'two transport chunks can contain many tokens','final':{
            'tokens_evaluated':15360,'tokens_predicted':512,'truncated':False,
            'timings':{'predicted_n':512,'predicted_ms':1000}}}
        self.assertEqual(validate_native(reply,15360,512),[])
        reply['final']['tokens_evaluated']=15359
        self.assertIn('prompt token mismatch',validate_native(reply,15360,512))
        reply['final']['truncated']=True
        self.assertIn('context truncation',validate_native(reply,15360,512))
    def test_missing_sample_breaks_overlap(self):
        self.assertEqual(overlap([{'t_s':0,'active':5},{'t_s':1,'active':None},{'t_s':2,'active':5}],5),0)
        self.assertEqual(overlap([{'t_s':0,'active':5},{'t_s':1,'active':5}],5),1)
    def test_truncation_is_fail_output(self):
        """Context truncation must produce FAIL_OUTPUT validation error."""
        reply={'text':'some text','final':{
            'tokens_evaluated':15872,'tokens_predicted':510,'truncated':True,
            'timings':{'predicted_n':510,'predicted_ms':60000}}}
        errors=validate_native(reply,15872,512)
        self.assertIn('context truncation',errors)
        self.assertIn('completion token mismatch',errors)
    def test_pass_reply_has_no_errors(self):
        reply={'text':'good output','final':{
            'tokens_evaluated':1024,'tokens_predicted':512,'truncated':False,
            'timings':{'predicted_n':512,'predicted_ms':5000}}}
        self.assertEqual(validate_native(reply,1024,512),[])
    def test_empty_text_is_failure(self):
        reply={'text':'','final':{
            'tokens_evaluated':1024,'tokens_predicted':512,'truncated':False,
            'timings':{'predicted_n':512,'predicted_ms':5000}}}
        self.assertIn('empty output',validate_native(reply,1024,512))
    def test_missing_decode_duration_is_failure(self):
        reply={'text':'output','final':{
            'tokens_evaluated':1024,'tokens_predicted':512,'truncated':False,
            'timings':{'predicted_n':512,'predicted_ms':0}}}
        self.assertIn('missing native decode duration',validate_native(reply,1024,512))
    def test_overlap_continuous_full(self):
        """Full overlap for 3 samples at target concurrency."""
        samples=[{'t_s':0,'active':5},{'t_s':1,'active':5},{'t_s':3,'active':5}]
        self.assertEqual(overlap(samples,5),3)
    def test_overlap_partial_break(self):
        """Break in the middle resets the window."""
        samples=[{'t_s':0,'active':5},{'t_s':1,'active':4},{'t_s':2,'active':5},{'t_s':4,'active':5}]
        self.assertEqual(overlap(samples,5),2)
if __name__=='__main__':unittest.main()

