import json
from pathlib import Path
import sys
import tempfile
import unittest
from unittest.mock import patch
sys.path.insert(0, str(Path(__file__).resolve().parents[1]/'scripts'))
import run_track_v_remote as runner


class SmokeIntegrity(unittest.TestCase):
    def test_valid_and_rejected_responses(self):
        changes = [({}, True), ({'truncated': True}, False), ({'stop_type': 'limit'}, False),
                   ({'tokens_evaluated': 1}, False), ({'content': 'garbage'}, False), ({'stop': False}, False), ({'stop_type': None}, False),
                   ({'content': '{"project":"V1","answer":17}'}, False)]
        for change, expected in changes:
            with self.subTest(change=change), tempfile.TemporaryDirectory() as directory:
                def fake_http(path, payload=None, timeout=10):
                    if path == '/apply-template':
                        return {'prompt': 'test'}
                    if path == '/tokenize':
                        return {'tokens': [1, 2]}
                    return {'content': '{"project":"V0","answer":17}', 'stop_type': 'eos',
                            'tokens_evaluated': 2, 'truncated': False, 'stop': True, **change}
                with patch.object(runner, 'http', fake_http):
                    result = runner.smoke_request(0, Path(directory), 0)
                self.assertEqual(result['pass'], expected)
                saved = json.loads((Path(directory)/'smoke-0-result.json').read_text())
                self.assertEqual(saved, result)

    def test_wrong_host_refuses_execution(self):
        with patch.object(runner.platform, 'node', return_value='laptop'):
            with self.assertRaisesRegex(ValueError, 'p520-llm'):
                runner.execute(None)


if __name__ == '__main__':
    unittest.main()

